/* Validación individual de preguntas importadas, contrastada con guías. Los estados discutibles quedan sin puntuación. */
Object.assign(KEY["pdf-novas-1"]["1"],{"a":"A","status":"validado","why":"El dolor abdominal súbito intenso desproporcionado al examen, con lactato elevado, acidosis y vasculopatía, obliga a descartar de urgencia isquemia mesentérica aguda con angio-TC y valoración quirúrgica.","o":{"B":"La pancreatitis suele acompañarse de elevación de lipasa y dolor epigástrico característico.","C":"La colitis isquémica suele presentar dolor y hematoquecia; no es la presentación más preocupante aquí.","D":"La apendicitis se localiza habitualmente en fosa ilíaca derecha, con signos locales progresivos."},"src":"World Society of Emergency Surgery, Acute Mesenteric Ischemia 2022","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9580452/"});
Object.assign(KEY["pdf-novas-1"]["2"],{"a":"A","status":"validado","why":"La imagen compatible con coledocolitiasis distal sintomática después de colecistectomía orienta a extracción por CPRE con eventual esfinterotomía; no precisa reabrir el abdomen de primera intención.","o":{"B":"La exploración quirúrgica del colédoco se reserva para determinadas circunstancias o fracaso endoscópico.","C":"La extracción mediante tubo de Kehr exige que el paciente tenga ese drenaje, ausente en el caso.","D":"Una anastomosis biliodigestiva abierta no es primera elección para un cálculo distal común."},"src":"NICE, Gallstone disease: diagnosis and management","src_url":"https://www.nice.org.uk/guidance/cg188/chapter/recommendations"});
Object.assign(KEY["pdf-novas-1"]["3"],{"a":"C","status":"validado","why":"El adenocarcinoma resecable de cabeza pancreática se trata habitualmente con duodenopancreatectomía cefálica (Whipple) y linfadenectomía regional, dentro de un plan oncológico multidisciplinario.","o":{"A":"La enucleación no es una resección oncológica suficiente de un adenocarcinoma.","B":"La pancreaticoyeyunostomía es parte de la reconstrucción, no la resección tumoral.","D":"La pancreatectomía distal se utiliza para tumores del cuerpo o cola pancreáticos."},"src":"NCI, Pancreatic Cancer Treatment (PDQ)","src_url":"https://www.cancer.gov/types/pancreatic/hp/pancreatic-treatment-pdq"});
Object.assign(KEY["pdf-novas-1"]["4"],{"a":"D","status":"discutible","why":"Fiebre persistente y oliguria tras cirugía abdominal con anastomosis hacen sospechar complicación séptica intraabdominal, incluida fuga anastomótica, pero no permiten confirmar D ni descartar colección/absceso sin exploración, TC y evaluación de sepsis. La cronología del enunciado es internamente confusa.","o":{"A":"Peritonitis posoperatoria también es posible y puede ser consecuencia de una fuga.","B":"Endocarditis no es la primera explicación, salvo signos o bacteriemia específicos.","C":"La sepsis postesplenectomía existe, pero el foco abdominal temprano debe ser investigado."},"src":"WHO Global Guidelines for Prevention of Surgical Site Infection","src_url":"https://www.who.int/publications/i/item/9789241550475"});
Object.assign(KEY["pdf-novas-1"]["5"],{"a":"C","status":"validado","why":"La infiltración preincisional de anestésico local busca disminuir la nocicepción perioperatoria y el dolor posoperatorio como parte de analgesia multimodal; el beneficio depende de técnica y contexto.","o":{"A":"La hemostasia no es el objetivo principal del anestésico local sin vasoconstrictor.","B":"La infiltración no se indica principalmente para facilitar la disección anatómica.","D":"Puede mitigar respuesta simpática, pero la finalidad primaria es analgesia."},"src":"WHO Global Guidelines for Prevention of Surgical Site Infection","src_url":"https://www.who.int/publications/i/item/9789241550475"});
Object.assign(KEY["pdf-novas-1"]["6"],{"a":"C","status":"validado","why":"Masa dolorosa por debajo del ligamento inguinal en una mujer mayor es muy sugestiva de hernia femoral o crural, con riesgo importante de estrangulación y valoración quirúrgica urgente.","o":{"A":"La hernia inguinal directa emerge por encima del ligamento inguinal.","B":"La hernia inguinal indirecta también aparece por encima del ligamento, siguiendo canal inguinal.","D":"La hernia obturatriz suele ser profunda y difícil de palpar como masa femoral superficial."},"src":"NICE, Gallstone disease: diagnosis and management","src_url":"https://www.nice.org.uk/guidance/cg188/chapter/recommendations"});
Object.assign(KEY["pdf-novas-1"]["7"],{"a":"D","status":"discutible","why":"Picos febriles y leucocitosis después de cirugía por apendicitis orientan a absceso intraabdominal posoperatorio; la localización subfrénica no se puede inferir sin imágenes. Además la cronología de la cirugía, alta y fiebre se contradice. Requiere TC abdominal para identificar el foco.","o":{"A":"Sinusitis aguda no explica de modo convincente el contexto posoperatorio abdominal.","B":"Peritonitis difusa suele dar mayor irritación peritoneal y deterioro, pero no queda excluida.","C":"Pielonefritis requiere correlación urinaria y examen para justificar su prioridad."},"src":"WHO Global Guidelines for Prevention of Surgical Site Infection","src_url":"https://www.who.int/publications/i/item/9789241550475"});
Object.assign(KEY["pdf-novas-1"]["8"],{"a":"B","status":"validado","why":"En colelitiasis incidental sin cólico biliar ni complicación, la conducta habitual es expectante; la distensión posprandial inespecífica no demuestra cólico biliar.","o":{"A":"No hay indicación de colecistectomía urgente por distensión aislada.","C":"La técnica abierta no previene por sí misma cáncer vesicular; no está indicada profilaxis universal.","D":"El sexo femenino por sí solo no indica colecistectomía profiláctica."},"src":"NICE, Gallstone disease: diagnosis and management","src_url":"https://www.nice.org.uk/guidance/cg188/chapter/recommendations"});
Object.assign(KEY["pdf-novas-1"]["9"],{"a":"C","status":"validado","why":"La clasificación ASA V corresponde a paciente moribundo que no se espera que sobreviva sin la operación; no equivale simplemente a enfermedad sistémica grave.","o":{"A":"ASA V no representa riesgo leve.","B":"La enfermedad sistémica grave corresponde a ASA III; si constituye amenaza constante para la vida, ASA IV.","D":"La relación de la enfermedad con la patología quirúrgica no define por sí sola ASA V."},"src":"American Society of Anesthesiologists, ASA Physical Status","src_url":"https://doi.org/10.1097/ao9.0000000000000002"});
Object.assign(KEY["pdf-novas-2"]["1"],{"a":null,"status":"discutible","why":"GABARITO ORIGINAL D NO VÁLIDO: HBsAg positivo y anti-HBs negativo indican infección por VHB, pero no permiten diferenciar infección aguda de crónica sin IgM anti-HBc, cronología y/o persistencia de HBsAg durante 6 meses. HBcAg no es el marcador sérico que sustituye anti-HBc. No hay opción única entre A y D.","o":{"A":"La hepatitis B crónica es posible si HBsAg persiste al menos seis meses.","B":"Hepatitis fulminante requiere evidencia de falla hepática aguda, no suministrada.","C":"La inmunidad por vacuna se caracteriza por anti-HBs positivo aislado.","D":"Hepatitis B aguda es posible, pero requiere IgM anti-HBc y evolución clínica."},"src":"CDC, Clinical Testing and Diagnosis for Hepatitis B","src_url":"https://www.cdc.gov/hepatitis-b/hcp/diagnosis-testing/"});
Object.assign(KEY["pdf-novas-2"]["2"],{"a":"C","status":"validado","why":"CORRECCIÓN DE CLAVE D → C: alteración del estado mental está reconocida entre factores que predicen evolución desfavorable de pancreatitis aguda (BISAP). Los puntos de corte de las otras opciones son inadecuados: edad de riesgo >55 y obesidad IMC >30; Hto elevado clínicamente significativo no se define por >35%.","o":{"A":"Hematocrito de 35% no es marcador de hemoconcentración pronóstica.","B":"IMC apenas >25 no corresponde a obesidad y no es umbral de riesgo de guías.","D":"La edad >40 aislada no es el umbral de predicción habitual (se usa >55 o >60 según escala)."},"src":"ACG, Management of Acute Pancreatitis 2024","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13221274/"});
Object.assign(KEY["pdf-novas-2"]["3"],{"a":"A","status":"validado","why":"El dolor epigástrico súbito con peritonismo e historia de AINE sugiere perforación de úlcera péptica. Una radiografía de tórax en bipedestación puede evidenciar neumoperitoneo; la TC tiene mejor sensibilidad cuando el paciente está estable. Inestabilidad y peritonismo requieren cirugía urgente sin demorar por pruebas.","o":{"B":"El hematocrito no confirma perforación de víscera hueca.","C":"Leucocitosis es inespecífica y no localiza perforación.","D":"La ecografía tiene menor utilidad para detectar aire libre frente a radiografía/TC."},"src":"WSES Guidelines, Perforated and Bleeding Peptic Ulcer","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6947898/"});
Object.assign(KEY["pdf-novas-2"]["4"],{"a":"A","status":"discutible","why":"GABARITO PDF A DUDOSO: consumo elevado de alcohol, hepatomegalia e ictericia obligan a evaluar hepatopatía; sin embargo ALT/TGP 240 es mayor que AST/TGO 125, patrón no típico de hepatitis asociada al alcohol (habitualmente AST/ALT >1,5). Se deben investigar hepatitis viral, medicamentosa, obstrucción y otras causas. No se confirma etiología solo con lo aportado.","o":{"B":"Cirrosis avanzada no puede establecerse por estos datos sin evaluación de función hepática, fibrosis e imagen.","C":"Insuficiencia hepática severa requiere coagulopatía y otros criterios de fallo, no informados.","D":"Hepatitis viral es diagnóstico diferencial importante por patrón hepatocelular; requiere serologías."},"src":"ACG, Management of Acute Pancreatitis 2024","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC13221274/"});
Object.assign(KEY["pdf-novas-2"]["5"],{"a":"B","status":"discutible","why":"Paciente internado con distensión colónica generalizada sugiere pseudoobstrucción colónica aguda (Ogilvie). Primero se descarta obstrucción mecánica, isquemia/perforación, se corrigen electrolitos y fármacos y se aplica descompresión conservadora. Neostigmina o colonoscopia se reservan para fracaso del manejo inicial, dilatación importante o curso prolongado. Falta diámetro cecal y tratamientos ya realizados.","o":{"A":"Cecostomía es excepcional y más invasiva, no el primer abordaje rutinario.","C":"Laparotomía se reserva para isquemia, perforación o fracaso de medidas no quirúrgicas.","D":"Hemicolectomía no se indica en pseudoobstrucción simple sin daño intestinal."},"src":"ASGE, acute colonic pseudo-obstruction 2020","src_url":"https://www.asge.org/home/resources/publications/guidelines/american-society-for-gastrointestinal-endoscopy-guideline-on-the-role-of-endoscopy-in-the-management-of-acute-colonic-pseudo-obstruction-and-colonic-volvulus"});
Object.assign(KEY["pdf-novas-2"]["6"],{"a":"B","status":"validado","why":"Paciente con cáncer avanzado y uso de morfina: estreñimiento relacionado con opioides sin signos de obstrucción. Se evalúa fecaloma mediante tacto rectal y se comienza laxante osmótico o estimulante según clínica; corregir el error tipográfico «impactación fetal» por «impactación fecal».","o":{"A":"Reducir el opioide a la mitad puede descontrolar el dolor y no es primera elección.","C":"Un procinético gástrico no sustituye los laxantes indicados para estreñimiento por opioides.","D":"Sin vómitos, abdomen patológico ni alarma no hay indicación automática de TC urgente."},"src":"American Gastroenterological Association, Constipation medical position statement","src_url":"https://gastrojournal.org/article/S0016-5085(12)01056-2/fulltext"});
Object.assign(KEY["pdf-novas-2"]["7"],{"a":"A","status":"validado","why":"En el sobrecrecimiento bacteriano del intestino delgado, las pruebas diagnósticas habituales son tests de aliento o aspirado/cultivo intestinal en casos seleccionados; la biopsia no constituye la prueba diagnóstica de rutina.","o":{"B":"Puede existir anemia por malabsorción de vitamina B12 o nutrientes.","C":"Cirugía digestiva previa favorece estasis y sobrecrecimiento.","D":"Diarrea, distensión y malabsorción son presentaciones reconocidas."},"src":"ACG Clinical Guideline, Small Intestinal Bacterial Overgrowth","src_url":"https://pubmed.ncbi.nlm.nih.gov/32023228/"});
Object.assign(KEY["pdf-novas-2"]["8"],{"a":"D","status":"validado","why":"Varón joven atópico con episodios de impactación alimentaria y disfagia es sugestivo de esofagitis eosinofílica; se confirma con endoscopia y biopsias. Incapacidad para tragar saliva exige endoscopia urgente por obstrucción esofágica completa.","o":{"A":"El esófago de Barrett se relaciona con reflujo crónico y no es causa típica de impactación en joven atópico.","B":"El anillo de Schatzki causa disfagia intermitente a sólidos, pero la fuerte atopia orienta más a EoE.","C":"La esofagitis infecciosa suele cursar con odinofagia y en inmunodepresión."},"src":"ACG Clinical Guideline, Eosinophilic Esophagitis","src_url":"https://pubmed.ncbi.nlm.nih.gov/39745304/"});
Object.assign(KEY["pdf-novas-2"]["9"],{"a":"C","status":"validado","why":"Úlcera en cara posterior de bulbo duodenal puede erosionar arteria gastroduodenal. Forrest Ib (sangrado en napa) tiene riesgo de resangrado y requiere hemostasia eficaz; adrenalina endoscópica como único método NO es suficiente según guías actuales, debe combinarse con clip o terapia térmica.","o":{"A":"Forrest Ib implica sangrado activo y riesgo de recidiva no bajo.","B":"Ante resangrado es posible segundo tratamiento endoscópico; la cirugía no es obligatoria de entrada.","D":"La vagotomía troncular ya no es procedimiento universal obligatorio ante sangrado ulceroso."},"src":"ACG, Upper Gastrointestinal and Ulcer Bleeding 2021","src_url":"https://pubmed.ncbi.nlm.nih.gov/33929377/"});
Object.assign(KEY["pdf-novas-2"]["10"],{"a":"A","status":"validado","why":"El déficit de B12 por gastritis autoinmunitaria del cuerpo gástrico se asocia con atrofia oxíntica, metaplasia intestinal e hiperplasia de células enterocromafines; H. pylori no es hallazgo morfológico necesario o característico en la biopsia corporal, aunque infección concomitante puede existir.","o":{"B":"La metaplasia intestinal puede observarse en la gastritis atrófica crónica.","C":"La hiperplasia de células neuroendocrinas ECL es típica por hipergastrinemia.","D":"La atrofia de glándulas oxínticas es el sustrato clásico de anemia perniciosa."},"src":"ACG/CAG Clinical Practice Guidelines on the Management of Dyspepsia","src_url":"https://pubmed.ncbi.nlm.nih.gov/28631728/"});
Object.assign(KEY["pdf-novas-2"]["11"],{"a":"D","status":"validado","why":"Anemia ferropénica severa en mujer posmenopáusica obliga a investigar pérdida digestiva, especialmente colon, aunque endoscopia alta encuentre hernia hiatal pequeña sin esofagitis. La videocolonoscopia es el paso clave para descartar lesión colorrectal.","o":{"A":"Hierro oral trata el déficit, pero sin investigar causa digestiva de anemia en posmenopausia es insuficiente.","B":"IBP para pirosis no resuelve la etiología de la anemia.","C":"La cápsula endoscópica se considera posteriormente si endoscopia alta y colonoscopia no explican la anemia."},"src":"ACG, Upper Gastrointestinal and Ulcer Bleeding 2021","src_url":"https://pubmed.ncbi.nlm.nih.gov/33929377/"});
Object.assign(KEY["pdf-novas-2"]["12"],{"a":"C","status":"validado","why":"La mayoría de pacientes con síntomas dispépticos no tienen úlcera u otra lesión estructural y cumplen criterios de dispepsia funcional; requiere excluir signos de alarma y seguir evaluación acorde con edad.","o":{"A":"Alcohol puede agravar síntomas pero no es la etiología principal global.","B":"La úlcera péptica es causa orgánica, proporcionalmente menos frecuente.","D":"AINE favorece gastritis/úlcera pero no explica la mayoría de dispepsias."},"src":"ACG/CAG Clinical Practice Guidelines on the Management of Dyspepsia","src_url":"https://pubmed.ncbi.nlm.nih.gov/28631728/"});
Object.assign(KEY["pdf-novas-2"]["13"],{"a":"D","status":"validado","why":"Polietilenglicol (PEG o macrogol) retiene agua por efecto osmótico en el lumen intestinal, ablandando heces y facilitando su eliminación.","o":{"A":"No aumenta masa por fibras fermentables como psyllium.","B":"No es laxante estimulante directo del peristaltismo como bisacodilo.","C":"No actúa recubriendo o lubricando heces como aceite mineral."},"src":"American Gastroenterological Association, Constipation medical position statement","src_url":"https://gastrojournal.org/article/S0016-5085(12)01056-2/fulltext"});
Object.assign(KEY["pdf-novas-3"]["1"],{"a":"A","status":"validado","why":"Ante sospecha de fractura de base de cráneo o trauma mediofacial importante, debe evitarse paso ciego de sonda por vía nasal por riesgo de colocación intracraneal. Preferir vía orogástrica si está indicada.","o":{"B":"Fracturas orbitales/mandibulares aisladas no equivalen siempre a fractura de base; valorar anatomía y lesiones específicas.","C":"Epistaxis es precaución y puede impedir el procedimiento, pero el principal criterio anatómico absoluto ofrecido es fractura de base.","D":"Fractura de suelo orbitario aislada no define la misma contraindicación anatómica."},"src":"American College of Surgeons, ATLS principles","src_url":"https://www.facs.org/quality-programs/trauma/education/advanced-trauma-life-support/"});
Object.assign(KEY["pdf-novas-3"]["2"],{"a":"D","status":"discutible","why":"La conducta inicial depende del tipo, ubicación y síntomas del cuerpo extraño. Radiografía de cuello/tórax sirve si es radiopaco o desconocido; batería botón, objeto punzante u obstrucción esofágica completa requieren endoscopia urgente, sin demoras. Faltan esos datos para seleccionar universalmente D frente a C.","o":{"A":"Dar grandes cantidades de agua puede agravar obstrucción o aspiración.","B":"Espasmolíticos no son medida inicial indicada para cuerpo extraño esofágico.","C":"La esofagoscopia es prioritaria si existe obstrucción completa, pila botón o objeto punzante; no universal en todos los casos."},"src":"ASGE, ingested foreign bodies and food impactions","src_url":"https://www.asge.org/home/resources/publications/guidelines/management-of-ingested-foreign-bodies-and-food-impactions"});
Object.assign(KEY["pdf-novas-3"]["3"],{"a":"D","status":"validado","why":"La secuencia propuesta más cercana a la cadena de supervivencia es reconocimiento de paro y activación de emergencias, RCP precoz, desfibrilación temprana, atención avanzada y cuidados posresucitación. La opción D simplifica la cadena, pero respeta el orden fundamental.","o":{"A":"Anteponer desfibrilación al pedido de ayuda y reconocimiento del paro omite la secuencia inicial.","B":"Abrir vía aérea antes de activar servicios y no iniciar RCP omite un eslabón esencial.","C":"Demorar reconocimiento/solicitud de ayuda y desfibrilación reduce posibilidades de supervivencia."},"src":"American Heart Association, Adult BLS 2025","src_url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support/"});
Object.assign(KEY["pdf-novas-3"]["4"],{"a":"A","status":"validado","why":"Traumatismo abdominal cerrado con hipotensión y taquicardia, palidez y diaforesis sugiere hemorragia interna y choque hipovolémico hemorrágico hasta demostrar lo contrario.","o":{"B":"No hay foco infeccioso ni evolución para choque séptico.","C":"Choque cardiogénico implica falla de bomba y no es la principal hipótesis tras trauma abdominal.","D":"Choque neurogénico suele asociarse a lesión medular y puede producir bradicardia relativa."},"src":"American College of Surgeons, ATLS principles","src_url":"https://www.facs.org/quality-programs/trauma/education/advanced-trauma-life-support/"});
Object.assign(KEY["pdf-novas-3"]["5"],{"a":"B","status":"validado","why":"Quemadura dérmica superficial de espesor parcial o segundo grado puede ser muy dolorosa, con ampollas y superficie húmeda/exudativa; profundidad y sensibilidad cambian si la lesión es más profunda.","o":{"A":"Superficie muy dura y seca sugiere quemadura más profunda, no patrón superficial típico.","C":"Dolor escaso o ausente orienta a lesión de espesor completo o profunda.","D":"Eritema sin ampollas es más típico de lesión superficial de primer grado."},"src":"American College of Surgeons, ATLS principles","src_url":"https://www.facs.org/quality-programs/trauma/education/advanced-trauma-life-support/"});
Object.assign(KEY["pdf-novas-3"]["6"],{"a":"B","status":"validado","why":"Compresiones de RCP del adulto a 100–120 por minuto, con profundidad de 5–6 cm, descompresión completa y mínimas interrupciones, según recomendaciones AHA 2025.","o":{"A":"100–150 incluye frecuencias excesivas por encima del límite superior recomendado.","C":"80–100 queda por debajo del rango recomendado en buena parte del intervalo.","D":"60–100 también es demasiado lento para RCP de alta calidad."},"src":"American Heart Association, Adult BLS 2025","src_url":"https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/adult-basic-life-support/"});
Object.assign(KEY["pdf-novas-3"]["7"],{"a":"C","status":"validado","why":"La evaluación primaria del trauma sigue ABCDE: A vía aérea con protección cervical, B ventilación, C circulación y control de hemorragia, D discapacidad neurológica, E exposición y prevención de hipotermia.","o":{"A":"Prioriza circulación antes de respiración, alterando el ABCDE.","B":"Prioriza respiración antes de vía aérea y su protección cervical.","D":"Inicia por respiración/exposición sin asegurar vía aérea o controlar secuencia ABCDE."},"src":"American College of Surgeons, ATLS principles","src_url":"https://www.facs.org/quality-programs/trauma/education/advanced-trauma-life-support/"});

/* Validación científica individual: ginecología y hematología */
Object.assign(KEY["pdf-novas-4"]["1"],{"a":"A","status":"validado","why":"En preeclampsia, plaquetas inferiores a 100.000/µL representan compromiso hematológico grave, incluso sin hipertensión extrema. Las demás opciones aisladas no son criterios de severidad.","o":{"B":"El edema periférico es inespecífico y muy frecuente en gestación.","C":"Proteinuria 1+ aislada no define severidad ni constituye cuantificación adecuada.","D":"Presión arterial 140/90 señala hipertensión, pero no hipertensión de rango grave (≥160/110)."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["2"],{"a":"B","status":"discutible","why":"El caso sugiere síndrome de ovario poliquístico por oligomenorrea, acné y sobrepeso, pero en mujeres adultas con ciclos irregulares e hiperandrogenismo clínico la ecografía NO es obligatoria para establecer diagnóstico; también deben excluirse otras causas (TSH, prolactina, 17-OHP según contexto). Por eso la afirmación de que ecografía transvaginal es estudio de mayor valor no es universal.","o":{"A":"Ecografía tiroidea no evalúa función tiroidea y no es prueba inicial de SOP.","C":"La determinación de hormonas tiroideas puede ser útil para excluir diagnóstico alternativo, sin confirmar SOP.","D":"La TC abdominal no es método diagnóstico estándar para SOP."},"src":"Guía internacional basada en evidencia para síndrome de ovario poliquístico, 2023","src_url":"https://academic.oup.com/humrep/article/38/9/1655/7241786"});
Object.assign(KEY["pdf-novas-4"]["3"],{"a":"A","status":"validado","why":"Rotura prematura de membranas con fiebre, taquicardia materna, dolor y secreción fétida sugiere infección intraamniótica; se indican antibióticos intravenosos, estabilización y finalización del embarazo. La vía del parto depende de indicaciones obstétricas, no cesárea sistemática.","o":{"B":"Los antibióticos solos sin plan obstétrico no resuelven el foco cuando existe infección intraamniótica.","C":"La observación sin tratamiento expone a sepsis materno-fetal.","D":"La cesárea urgente no es obligatoria por corioamnionitis aislada; valorar condiciones de parto."},"src":"NICE NG25, parto prematuro y rotura prematura de membranas","src_url":"https://www.nice.org.uk/guidance/ng25/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["4"],{"a":"A","status":"validado","why":"Miomas uterinos sintomáticos con sangrado importante y deseo de fertilidad hacen considerar tratamiento conservador del útero; la miomectomía es opción entre las ofrecidas. Valorar localización, distorsión endometrial, síntomas, reserva reproductiva y preferencias.","o":{"B":"La histerectomía elimina la fertilidad y contradice deseo reproductivo.","C":"La embolización puede afectar fertilidad y no es opción preferida en todas las que desean gestación.","D":"Los agonistas GnRH pueden reducir temporalmente volumen/sangrado, pero no son solución definitiva habitual."},"src":"ACOG, Uterine Fibroids","src_url":"https://www.acog.org/womens-health/faqs/uterine-fibroids"});
Object.assign(KEY["pdf-novas-4"]["5"],{"a":"A","status":"validado","why":"La metrorragia posmenopáusica bajo tamoxifeno requiere estudio histológico del endometrio; la histeroscopia con biopsia dirigida es adecuada dada imagen quística/endometrio de 18 mm. No asumir benignidad por tamoxifeno ni decidir solo por grosor.","o":{"B":"Histerectomía total sin diagnóstico histológico previo es excesiva.","C":"El control habitual ignora sangrado posmenopáusico de alarma.","D":"Legrado endocervical aislado no evalúa de manera suficiente cavidad endometrial."},"src":"HSE Clinical Practice Guideline, Postmenopausal Bleeding (incluye tamoxifeno)","src_url":"https://www.hse.ie/eng/about/who/acute-hospitals-division/woman-infants/clinical-guidelines/assessment-and-management-of-postmenopausal-bleeding.pdf"});
Object.assign(KEY["pdf-novas-4"]["6"],{"a":"C","status":"validado","why":"Levetiracetam no induce enzimas hepáticas y por ello tiene menos interacción con anticonceptivos combinados que carbamazepina o fenobarbital. La selección definitiva depende del tipo de epilepsia, potencial de embarazo y asesoramiento preconcepcional.","o":{"A":"Carbamazepina induce enzimas y reduce eficacia de varios anticonceptivos hormonales.","B":"Fenobarbital es un potente inductor enzimático con numerosas interacciones.","D":"Valproato implica riesgos teratogénicos importantes; evitarlo en mujeres con potencial gestacional si alternativas son eficaces."},"src":"American Academy of Neurology, Antiseizure Medications During Pregnancy","src_url":"https://www.aan.com/Guidelines/home/GuidelineDetail/1108"});
Object.assign(KEY["pdf-novas-4"]["7"],{"a":"B","status":"validado","why":"Plaquetas 85.000, transaminasas elevadas y LDH 650 en preeclampsia grave cumplen datos compatibles con síndrome HELLP (hemólisis, enzimas hepáticas altas, plaquetas bajas). Requiere estabilización obstétrica y decisión de finalización del embarazo.","o":{"A":"El diagnóstico de preeclampsia grave es cierto, pero la constelación de laboratorio apunta específicamente a HELLP.","C":"Preeclampsia leve es incompatible con trombocitopenia y citólisis importantes.","D":"No hay datos específicos de síndrome urémico hemolítico; la tríada obstétrica caracteriza HELLP."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["8"],{"a":"D","status":"discutible","why":"La placenta previa y el desprendimiento prematuro de placenta son dos causas importantes de hemorragia en la segunda mitad de la gestación. La expresión «causa patológica más frecuente» depende de población y definición, sin especificarlas; las frecuencias reportadas se solapan. Se conserva D como propuesta histórica, sin nota.","o":{"A":"La rotura uterina es mucho menos frecuente y generalmente tiene factores de riesgo obstétrico.","B":"El desprendimiento prematuro de placenta también es causa relevante y puede ser muy grave.","C":"La rotura de vasa previa es una causa infrecuente de sangrado agudo fetal."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["9"],{"a":"B","status":"discutible","why":"El primer control prenatal incluye VIH, sífilis, hepatitis B, además de Chagas según riesgo epidemiológico y evaluación de toxoplasmosis según protocolo local. Sin embargo varias combinaciones contienen pruebas recomendables y omiten otras; no se especifica jurisdicción ni calendario 2026, por lo que B no representa un panel universal exclusivo.","o":{"A":"La rubéola puede evaluarse según inmunidad y antecedentes, sin sustituir sífilis.","C":"B reúne pruebas relevantes, pero no siempre constituye el panel completo y universal.","D":"La opción C también reúne serologías frecuentes en distintos protocolos, aunque omite Chagas."},"src":"CDC, STI Screening Recommendations during Pregnancy","src_url":"https://www.cdc.gov/std/treatment-guidelines/screening-recommendations.htm"});
Object.assign(KEY["pdf-novas-4"]["10"],{"a":"D","status":"discutible","why":"Las maniobras de Leopold I y II aportan a la identificación de situación fetal. La primera distingue qué polo ocupa el fondo; la segunda palpa dorso y partes pequeñas y ayuda a establecer situación/posición. El enunciado no especifica qué dimensión quiere determinar y D no es inequívoca.","o":{"A":"La tercera maniobra identifica la parte presentada y su movilidad.","B":"La segunda maniobra puede determinar situación y posición fetal mediante palpación del dorso y extremidades.","C":"La cuarta valora encajamiento y actitud de la presentación."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["11"],{"a":"B","status":"discutible","why":"Dolor súbito y sangrado intraparto con antecedente de cesárea hacen sospechar ruptura uterina sobre cicatriz previa, urgencia obstétrica. La opción B dice «dehiscencia» —que puede ser incompleta y paucisintomática—, y no ofrece explícitamente ruptura completa. Es más seguro mantenerla no puntuable y señalar evaluación/cesárea emergente según compromiso.","o":{"A":"Rotura de vasa previa suele manifestarse tras rotura de membranas con sufrimiento fetal.","C":"Dehiscencia cicatricial es la más cercana, pero no debe equipararse a ruptura uterina completa.","D":"Rotura de seno marginal no explica de forma típica el cuadro asociado a cicatriz previa."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["12"],{"a":"B","status":"validado","why":"La detección de fosfatidilglicerol en líquido amniótico es menos interferida por contaminación sanguínea que otras pruebas históricas de madurez pulmonar. Actualmente esas pruebas tienen un papel mucho menor porque las decisiones dependen de edad gestacional y contexto clínico.","o":{"A":"El cociente lecitina/esfingomielina puede afectarse por contaminación de la muestra.","C":"El test de Clements no es fiable en presencia de sangre u otros contaminantes.","D":"La citología del líquido amniótico no es método preferido para valorar madurez surfactante."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["13"],{"a":"D","status":"validado","why":"La ecografía ginecológica transvaginal no constituye cribado rutinario de cáncer de ovario/endometrio en mujer asintomática de riesgo promedio. Los otros estudios pueden estar indicados según edad y esquema nacional (colonoscopia es una modalidad posible de cribado colorrectal, no necesariamente el único método).","o":{"A":"El Papanicolaou puede formar parte de prevención de cáncer cervical según pautas locales.","B":"La colonoscopia es una opción de cribado colorrectal en edades elegibles, aunque pueden usarse tests de heces.","C":"El perfil lipídico se indica según riesgo cardiometabólico; no implica ecografía ginecológica."},"src":"NCI, Cervical Cancer Causes/Risks/Prevention","src_url":"https://www.cancer.gov/types/cervical/causes-risk-prevention"});
Object.assign(KEY["pdf-novas-4"]["14"],{"a":"B","status":"validado","why":"Endometriosis suele manifestarse con dismenorrea, dolor pélvico y subfertilidad/infertilidad, aunque puede ser asintomática o causar dispareunia profunda y síntomas intestinales o urinarios cíclicos.","o":{"A":"La disuria es posible, pero menos característica que dismenorrea y dolor pélvico juntos.","C":"Tenesmo rectal puede ocurrir en enfermedad profunda pero no es síntoma principal general.","D":"Menometrorragia y anemia no constituyen la tríada típica de presentación."},"src":"ACOG, Uterine Fibroids","src_url":"https://www.acog.org/womens-health/faqs/uterine-fibroids"});
Object.assign(KEY["pdf-novas-4"]["15"],{"a":"B","status":"discutible","why":"El tabaquismo en menores de 35 años no se considera categoría 4 para anticonceptivos combinados por sí solo (generalmente categoría 2). Sin embargo la alternativa A mezcla hipertensión moderada (categoría 3) y severa (categoría 4), de modo que A tampoco representa siempre categoría 4. Falta grado de hipertensión y enunciado inequívoco.","o":{"A":"HTA moderada puede ser categoría 3; HTA grave ≥160/100 es categoría 4.","C":"El tabaquismo de cualquier intensidad antes de los 35 años no es automáticamente categoría 4.","D":"La migraña con aura es categoría 4 para anticonceptivos combinados."},"src":"OMS, Medical Eligibility Criteria for Contraceptive Use 2025","src_url":"https://www.ncbi.nlm.nih.gov/books/NBK619474/table/ch5.tab11/"});
Object.assign(KEY["pdf-novas-4"]["16"],{"a":"C","status":"validado","why":"Masa anexial quística compleja de 6 cm con proyección papilar en posmenopáusica exige descartar neoplasia ovárica. Se recomienda valoración especializada/oncoginecológica, caracterización de riesgo y eventual manejo quirúrgico; CA125 complementa pero no confirma diagnóstico.","o":{"A":"La TC por sí sola no sustituye valoración especializada y enfoque quirúrgico cuando la masa es sospechosa.","B":"CA125 y Doppler pueden ampliar estratificación pero no constituyen tratamiento definitivo frente a papila sospechosa.","D":"Esperar tres meses sin evaluación adicional puede retrasar diagnóstico de tumor."},"src":"NCI, Breast Cancer Treatment (PDQ)","src_url":"https://www.cancer.gov/types/breast/hp/breast-treatment-pdq"});
Object.assign(KEY["pdf-novas-4"]["17"],{"a":"B","status":"validado","why":"En muerte fetal retenida puede desarrollarse coagulopatía por consumo/coagulación intravascular diseminada, una complicación materna grave; su riesgo depende del tiempo y causas de óbito, por lo que se evalúan coagulación y fibrinógeno.","o":{"A":"Hemorragia puede complicar el cuadro pero la coagulopatía es complicación sistémica especialmente temida.","C":"Infección puede ocurrir, sin ser la complicación de consumo específica.","D":"Eclampsia no es consecuencia necesaria del óbito fetal aislado."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["18"],{"a":"B","status":"validado","why":"VPH 16 y 18, tipos oncogénicos, causan aproximadamente 70% de los cánceres cervicouterinos a nivel mundial.","o":{"A":"VPH 6 y 11 son de bajo riesgo y se relacionan con verrugas genitales.","C":"VPH 40 y 42 no son los principales tipos carcinogénicos.","D":"VPH 54 y 61 tampoco explican la mayoría de neoplasias cervicales."},"src":"NCI, Cervical Cancer Causes/Risks/Prevention","src_url":"https://www.cancer.gov/types/cervical/causes-risk-prevention"});
Object.assign(KEY["pdf-novas-4"]["19"],{"a":"B","status":"validado","why":"Secreción espontánea, unilateral, por un único conducto y sanguinolenta es patológica; citología negativa tiene sensibilidad insuficiente para descartar cáncer. Corresponde evaluación mamaria dirigida y estudios por imagen, con biopsia según hallazgos.","o":{"A":"Citología negativa no excluye carcinoma ni permite abandonar evaluación.","C":"Citología positiva requiere estudio anatomopatológico y estadificación, no cirugía amplia automática sin contexto.","D":"La radioterapia no se indica por citología positiva del derrame sin diagnóstico y estadificación."},"src":"NCI, Breast Cancer Treatment (PDQ)","src_url":"https://www.cancer.gov/types/breast/hp/breast-treatment-pdq"});
Object.assign(KEY["pdf-novas-4"]["20"],{"a":"A","status":"validado","why":"Los inhibidores de ECA, incluido enalapril, deben suspenderse al confirmarse embarazo por riesgo fetal. Metildopa es alternativa compatible con gestación; según disponibilidad también se utilizan labetalol o nifedipina.","o":{"B":"Continuar enalapril mantiene exposición fetal inapropiada.","C":"Agregar diurético no corrige la contraindicación de enalapril.","D":"No corresponde esperar arbitrariamente TA sistólica >155 para sustituir tratamiento y controlar presión."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["21"],{"a":"B","status":"validado","why":"Antes de iniciar anticonceptivo combinado, medir la presión arterial es un requisito esencial de seguridad. No se requiere rutinariamente PAP, ecografía, laboratorio hepático ni exploración pelviana en mujer sana.","o":{"A":"Papanicolaou y enzimas hepáticas no son condición de inicio del método.","C":"Laboratorio y ecografía vaginal indiscriminados añaden intervenciones sin indicación.","D":"PAP de cribado no debe usarse como barrera a anticoncepción."},"src":"OMS, Medical Eligibility Criteria for Contraceptive Use 2025","src_url":"https://www.ncbi.nlm.nih.gov/books/NBK619474/table/ch5.tab11/"});
Object.assign(KEY["pdf-novas-4"]["22"],{"a":"D","status":"discutible","why":"Cervicitis purulenta en mujer joven con pareja con uretritis precisa NAAT para gonococo/clamidia e inicio empírico oportuno; ceftriaxona y doxiciclina 7 días son preferidos cuando se sospechan ambos. La clave histórica D usa azitromicina en lugar de doxiciclina y depende de pauta vigente y prevalencia; ninguna opción refleja perfectamente conducta actual.","o":{"A":"Metronidazol aislado no trata gonorrea ni clamidia.","B":"Aguardar cultivo antes del tratamiento puede prolongar transmisión y complicaciones.","C":"Internación/ecografía urgente no está justificada sin dolor ni criterios de EPI grave; la combinación ceftriaxona-doxiciclina es apropiada."},"src":"CDC, Urethritis and Cervicitis","src_url":"https://www.cdc.gov/std/treatment-guidelines/urethritis-and-cervicitis.htm"});
Object.assign(KEY["pdf-novas-4"]["23"],{"a":"C","status":"validado","why":"La candidiasis vulvovaginal recurrente en mujer obesa debe motivar evaluación de diabetes o hiperglucemia, por lo que glucemia es el estudio de mayor rendimiento de los propuestos.","o":{"A":"Orina completa no detecta de forma sensible diabetes ni explica recidivas por sí sola.","B":"Hormonas tiroideas no son la primera prueba ante esta sospecha clínica.","D":"Hemograma no caracteriza el factor metabólico predisponente."},"src":"CDC, Vulvovaginal Candidiasis, recurrent infections","src_url":"https://www.cdc.gov/std/treatment-guidelines/candidiasis.htm"});
Object.assign(KEY["pdf-novas-4"]["24"],{"a":"A","status":"validado","why":"Agenesia uterovaginal con ovarios normales, caracteres sexuales femeninos desarrollados y anomalía renal asociada es clásica de síndrome de Mayer-Rokitansky-Küster-Hauser (MRKH).","o":{"B":"La insensibilidad completa a andrógenos presenta cariotipo 46,XY y testículos, no ovarios normales.","C":"Hiperplasia suprarrenal congénita puede causar virilización, no ausencia uterina con ovarios habituales.","D":"SOP no produce agenesia uterovaginal."},"src":"NCI, Cervical Cancer Causes/Risks/Prevention","src_url":"https://www.cancer.gov/types/cervical/causes-risk-prevention"});
Object.assign(KEY["pdf-novas-4"]["25"],{"a":"B","status":"validado","why":"El progestágeno genera endometrio poco receptivo y ESPESA el moco cervical, dificultando paso espermático, además de participar en supresión de ovulación según método.","o":{"A":"La disminución de viscosidad cervical no es efecto anticonceptivo del progestágeno.","C":"No estimula la producción endógena de estrógenos como mecanismo principal.","D":"El aumento de estrógeno endógeno no es mecanismo anticonceptivo de gestágenos."},"src":"OMS, Medical Eligibility Criteria for Contraceptive Use 2025","src_url":"https://www.ncbi.nlm.nih.gov/books/NBK619474/table/ch5.tab11/"});
Object.assign(KEY["pdf-novas-4"]["26"],{"a":null,"status":"discutible","why":"GABARITO ORIGINAL B CLÍNICAMENTE INCORRECTO: cuadro sugerente de enfermedad pélvica inflamatoria requiere antibióticos de amplio espectro, normalmente ceftriaxona más doxiciclina por 14 días más metronidazol 14 días, según situación. Un DIU colocado no debe retirarse de rutina; seguimiento en 48–72 h y considerar retiro si no mejora o la paciente lo desea. La opción B propone retiro obligatorio, no incluye metronidazol y usa doxiciclina 10 días. Ninguna alternativa describe la conducta adecuada.","o":{"A":"Retirar DIU y dar óvulos no trata infección ascendente.","B":"Retiro automático, dosis insuficiente y antibióticos incompletos no siguen guías actuales.","C":"Esperar cultivos antes de antibióticos retrasa tratamiento de EPI.","D":"Analgesia y retiro sin antibióticos no evitan complicaciones ni infertilidad."},"src":"CDC, Pelvic Inflammatory Disease guidelines","src_url":"https://www.cdc.gov/std/treatment-guidelines/pid.htm"});
Object.assign(KEY["pdf-novas-4"]["27"],{"a":"C","status":"discutible","why":"Quiste de 7 cm con ecos finos compatibles con endometrioma y dismenorrea hace razonable considerar laparoscopia terapéutica, pero la conducta depende de síntomas, deseo reproductivo, reserva ovárica, sospecha de malignidad y experiencia quirúrgica. No toda paciente con solo 7 meses de búsqueda requiere cirugía inmediata; la clave C no es universal.","o":{"A":"Anticonceptivos alivian dolor, pero inhiben ovulación durante uso y no satisfacen búsqueda de embarazo activa.","B":"Tratamiento médico aislado puede ser válido para dolor, aunque no elimina el endometrioma.","D":"Laparoscopia puede ser apropiada si síntomas intensos o quiste grande, equilibrando pérdida de reserva ovárica."},"src":"ACOG, Uterine Fibroids","src_url":"https://www.acog.org/womens-health/faqs/uterine-fibroids"});
Object.assign(KEY["pdf-novas-4"]["28"],{"a":"B","status":"validado","why":"pH fetal en sangre de cuero cabelludo de 7,22 cae en intervalo límite/prepatológico (7,21–7,24) de protocolos históricos: repetir muestreo en 15–30 minutos si persiste cardiotocografía preocupante y parto no es inminente. En práctica actual la técnica se usa cada vez menos.","o":{"A":"Acidosis grave suele considerarse pH <7,20 y exige reacción urgente.","C":"No corresponde demorar 1–2 h ante registro preocupante con pH límite.","D":"No hay evidencia de error de muestra solo por valor de 7,22."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["29"],{"a":null,"status":"discutible","why":"PREGUNTA CLÍNICAMENTE PELIGROSA: neonata con signos de sífilis congénita y madre tratada por vía oral (tratamiento inadecuado en embarazo). No se debe esperar fondo oscuro ni VDRL para iniciar tratamiento. El régimen preferido es penicilina G cristalina IV 100.000–150.000 U/kg/día según edad, por 10 días; la dosis fija de 300.000 U/día y duración 10–15 días de C no es pauta segura universal. No hay alternativa correcta.","o":{"A":"Un VDRL no reactivo aislado del neonato no descarta infección congénita.","B":"Un VDRL reactivo aislado tampoco confirma de manera definitiva; penicilina benzatínica 2,4 millones semanal es dosis de adulto, NO de recién nacido.","C":"El fondo oscuro de lesión puede apoyar diagnóstico, pero no debe retrasar penicilina IV ajustada por peso y edad.","D":"La alergia materna no autoriza eritromicina neonatal; penicilina es tratamiento indicado."},"src":"AAP, Congenital Syphilis Evaluation and Treatment","src_url":"https://www.aap.org/en/patient-care/congenital-syphilis/congenital-syphilis-evaluation-and-treatment-guide/"});
Object.assign(KEY["pdf-novas-4"]["30"],{"a":"A","status":"validado","why":"Dolor y sangrado en embarazo precoz con test positivo obligan a localizar la gestación y descartar ectópico mediante ecografía transvaginal, asociando β-hCG cuantitativa y seguimiento según estabilidad.","o":{"B":"Legrado sin definir localización y viabilidad puede dañar embarazo intrauterino deseado.","C":"Progesterona no sustituye estudio de embarazo ectópico.","D":"Prostaglandinas sin confirmar diagnóstico pueden ser perjudiciales."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["31"],{"a":"B","status":"discutible","why":"La irrigación vaginal procede sobre todo de arterias vaginales y ramas cervicovaginales de la uterina, originadas en la circulación ilíaca interna. La redacción de «vésico-vaginal rama de hipogástrica» no es nomenclatura estándar única, aunque B se aproxima al origen interno; ninguna opción reproduce con precisión anatomía variable.","o":{"A":"La rama cervicovaginal no surge normalmente de la hemorroidal media como único tronco.","C":"La arteria vaginal puede nacer de ilíaca interna, de uterina o de otras ramas, no necesariamente una «vésico-vaginal» exclusiva.","D":"La femoral no es origen principal de arteria vaginal."},"src":"NICE NG133, hipertensión y preeclampsia en el embarazo","src_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-4"]["32"],{"a":"D","status":"validado","why":"Candidiasis vulvovaginal recurrente (≥3 episodios sintomáticos/año): confirmar diagnóstico/especie, valorar control de diabetes, inducción antifúngica prolongada y mantenimiento con fluconazol oral SEMANAL durante 6 meses si Candida albicans susceptible; D es la que más se aproxima al período recomendado, aunque no explicita la frecuencia oral.","o":{"A":"Un esquema corto de fluconazol sin mantenimiento no previene bien recurrencias.","B":"Tres meses de mantenimiento es inferior a los seis meses recomendados.","C":"Tres meses de terapia oral no es la duración habitual de mantenimiento, aunque inducción local prolongada puede servir."},"src":"CDC, Vulvovaginal Candidiasis, recurrent infections","src_url":"https://www.cdc.gov/std/treatment-guidelines/candidiasis.htm"});
Object.assign(KEY["pdf-novas-5"]["1"],{"a":"C","status":"validado","why":"La deficiencia de folato interfiere con síntesis de ADN y causa anemia megaloblástica de VCM elevado, habitualmente macrocítica.","o":{"A":"Anemia sideroblástica suele tener VCM bajo o dimorfismo, no macrocitosis habitual.","B":"La ferropenia causa anemia microcítica hipocrómica.","D":"Talasemias suelen producir microcitosis desproporcionada."},"src":"Merck Manual Professional, Evaluation of Anemia","src_url":"https://www.merckmanuals.com/professional/hematology-and-oncology/approach-to-the-patient-with-anemia/evaluation-of-anemia"});
Object.assign(KEY["pdf-novas-5"]["2"],{"a":"B","status":"validado","why":"La anisocitosis describe variación del tamaño de eritrocitos, reflejada en aumento de RDW (amplitud de distribución eritrocitaria).","o":{"A":"HCM mide hemoglobina por eritrocito, no variabilidad de tamaño.","C":"Hematocrito refleja fracción de volumen ocupada por eritrocitos.","D":"VCM es promedio del volumen corpuscular, no su dispersión."},"src":"Merck Manual Professional, Evaluation of Anemia","src_url":"https://www.merckmanuals.com/professional/hematology-and-oncology/approach-to-the-patient-with-anemia/evaluation-of-anemia"});
Object.assign(KEY["pdf-novas-5"]["3"],{"a":"B","status":"validado","why":"Granulomatosis con poliangeítis (antiguo Wegener) es vasculitis de pequeños-medianos vasos que afecta vías aéreas, pulmón y riñón; puede dar glomerulonefritis rápidamente progresiva.","o":{"A":"Takayasu afecta vasos de gran calibre, sobre todo aorta y ramas.","C":"Vasculitis por hipersensibilidad puede limitarse a piel; compromiso visceral importante no es definitorio.","D":"Granulomatosis eosinofílica con poliangeítis (Churg-Strauss) se asocia a EOSINOFILIA, no descenso."},"src":"American College of Rheumatology, Vasculitis","src_url":"https://rheumatology.org/patients/granulomatosis-with-polyangiitis"});
Object.assign(KEY["pdf-novas-5"]["4"],{"a":"C","status":"validado","why":"Varón mayor con anemia microcítica ferropénica (ferritina 12, hierro bajo, TIBC alto), estable hemodinámicamente: hierro y estudio digestivo bidireccional para descartar neoplasia u origen hemorrágico. Transfusión no se decide automáticamente por Hb 7,9 sin síntomas graves o inestabilidad. Se puede mantener hierro varios meses para restaurar depósitos.","o":{"A":"Transfusión sistemática por 7,9 sin valorar clínica es innecesaria y omite la búsqueda etiológica.","B":"Transfusión junto con endoscopia puede requerirse en casos sintomáticos/ischemia, no es rutina en estable.","D":"Suspender hierro por preparación de colonoscopia puede ser útil según protocolo, pero terminarlo al normalizar Hb sin reponer reservas es insuficiente."},"src":"AGA, Gastrointestinal Evaluation of Iron Deficiency Anemia","src_url":"https://www.asge.org/home/resources/publications/journal-scan/issue/american-gastroenterological-association-issues-guidelines-on-gi-evaluation-of-iron-deficiency-anemia"});
Object.assign(KEY["pdf-novas-5"]["5"],{"a":"D","status":"validado","why":"Fiebre, escalofríos, hipotensión y dolor lumbar durante los primeros minutos de concentrado eritrocitario son clásicos de reacción transfusional hemolítica aguda. Suspender inmediatamente, mantener acceso con suero, avisar hemoterapia y evaluar hemólisis.","o":{"A":"Contaminación bacteriana también causa fiebre/shock, pero dolor lumbar e inicio inmediato orientan a hemólisis.","B":"Reacción febril no hemolítica no suele provocar hipotensión importante y dolor lumbar.","C":"No basta atribuir cuadro grave al pequeño volumen de plasma residual."},"src":"International Society of Blood Transfusion, adverse reactions","src_url":"https://www.isbtweb.org/resources/clinical-transfusion.html"});
Object.assign(KEY["pdf-novas-5"]["6"],{"a":"B","status":"validado","why":"Reticulocitosis, LDH muy elevada, bilirrubina elevada y haptoglobina indetectable son compatibles con anemia hemolítica. La prueba de antiglobulina directa (Coombs) investiga mecanismo inmunitario.","o":{"A":"Sangre oculta digestiva se solicita en pérdida sanguínea, no discrimina hemólisis inmunitaria.","C":"Ferropenia/B12/folato no son la causa más sugerida con reticulocitos altos y hemólisis bioquímica.","D":"Aspirado medular no es la primera prueba para definir mecanismo inmune de hemólisis."},"src":"Merck Manual Professional, Evaluation of Anemia","src_url":"https://www.merckmanuals.com/professional/hematology-and-oncology/approach-to-the-patient-with-anemia/evaluation-of-anemia"});
Object.assign(KEY["pdf-novas-5"]["7"],{"a":"D","status":"validado","why":"Prurito puede ser síntoma de linfoma de Hodgkin, micosis fungoide y mastocitosis sistémica. No es manifestación característica definitoria de leucemia mieloide aguda.","o":{"A":"Hodgkin suele acompañarse de prurito generalizado en una proporción de pacientes.","B":"Micosis fungoide es linfoma cutáneo T y causa lesiones pruriginosas.","C":"La liberación de mediadores mastocitarios favorece picazón en mastocitosis."},"src":"Merck Manual Professional, Hematology and Oncology","src_url":"https://www.merckmanuals.com/professional/hematology-and-oncology"});
Object.assign(KEY["pdf-novas-4"]["9"],{"o":{"A":"La rubéola puede evaluarse según inmunidad y antecedentes, sin sustituir sífilis.","C":"La opción C también reúne serologías frecuentes en distintos protocolos, aunque omite Chagas.","D":"La opción D incorpora hepatitis C, pero omite VIH y sífilis."}});
Object.assign(KEY["pdf-novas-4"]["11"],{"o":{"A":"Rotura de vasa previa suele manifestarse tras rotura de membranas y sufrimiento fetal.","C":"La rotura de seno marginal no explica de forma típica el cuadro asociado a cicatriz previa.","D":"El abruptio puede causar dolor y sangrado, pero el antecedente de cesárea aumenta sospecha de ruptura."}});
Object.assign(KEY["pdf-novas-4"]["15"],{"o":{"A":"HTA moderada puede ser categoría 3; HTA grave (≥160/100) es categoría 4.","C":"La migraña con aura es categoría 4 para anticonceptivos combinados.","D":"La diabetes con complicaciones vasculares es contraindicación importante, categoría 3/4 según circunstancias."}});
Object.assign(KEY["pdf-novas-4"]["27"],{"o":{"A":"Anticonceptivos alivian dolor, pero inhiben ovulación durante uso y no satisfacen búsqueda de embarazo activa.","B":"Tratamiento médico aislado puede ser válido para dolor, aunque no elimina el endometrioma.","D":"Anexectomía unilateral en mujer joven con fertilidad deseada suele ser excesiva."}});
Object.assign(KEY["pdf-novas-4"]["31"],{"o":{"A":"La rama cervicovaginal no surge normalmente de la hemorroidal media como único tronco.","C":"La femoral no es origen principal de arteria vaginal.","D":"La arteria ilíaca externa no suele originar rama cervicovaginal principal."}});

/* Validação científica individual: infectologia */
Object.assign(KEY["pdf-novas-6"]["1"],{"a":"B","status":"validado","why":"Si completó la serie primaria antitetánica pero el último refuerzo fue hace 18 años, corresponde una dosis de toxoide tetánico-diftérico (Td/Tdap) por calendario, antes de cirugía electiva cuando sea posible. La profilaxis específica de heridas y la inmunoglobulina dependen de características de la herida, no de una cirugía limpia.","o":{"A":"Tras 18 años sin refuerzo la protección calendaria no está actualizada.","C":"Inmunoglobulina más vacuna se reserva para heridas de alto riesgo y vacunación desconocida/incompleta o inmunodeficiencia relevante.","D":"Inmunoglobulina sola no es intervención rutinaria en cirugía electiva con serie primaria completa."},"src":"CDC, Tetanus Clinical Guidance","src_url":"https://www.cdc.gov/tetanus/hcp/clinical-guidance/index.html"});
Object.assign(KEY["pdf-novas-6"]["2"],{"a":"C","status":"discutible","why":"Para evitar sobreinfección bacteriana de lesiones por varicela son prioritarios higiene, baño suave, uñas cortas y evitar rascado. Antihistamínicos pueden reducir prurito y rascado, pero no constituyen por sí solos un método de prevención demostrado y las opciones omiten medidas higiénicas principales.","o":{"A":"Aciclovir puede estar indicado en grupos seleccionados, pero no es medida estándar contra sobreinfección bacteriana.","B":"Hervir la ropa no sustituye higiene cutánea y cuidado de las lesiones.","D":"El antihistamínico alivia picor, no reemplaza medidas de cuidado cutáneo."},"src":"CDC, Varicella-Zoster exposure and prophylaxis","src_url":"https://www.cdc.gov/chickenpox/hcp/clinical-guidance/index.html"});
Object.assign(KEY["pdf-novas-6"]["3"],{"a":"B","status":"validado","why":"Vómitos y diarrea sin fiebre aproximadamente 4 horas después de consumir alimento compartido, con dos afectados, sugieren intoxicación por enterotoxina preformada de Staphylococcus aureus, incubación típica 30 minutos a 8 horas.","o":{"A":"Salmonella suele incubar más y causa fiebre/diarrea inflamatoria con mayor frecuencia.","C":"Shigella produce disentería y tiene incubación habitualmente superior a varias horas.","D":"E. coli comprende síndromes variados; con inicio tan rápido tras helado la enterotoxina estafilocócica es más probable."},"src":"CDC, Staphylococcal Food Poisoning","src_url":"https://www.cdc.gov/staph-food-poisoning/about/index.html"});
Object.assign(KEY["pdf-novas-6"]["4"],{"a":"D","status":"discutible","why":"El familiar fue diagnosticado de varicela AHORA y el almuerzo ocurrió una semana antes. La varicela es contagiosa aproximadamente 1–2 días ANTES del exantema, no necesariamente 7 días antes. Se debe determinar fecha del inicio del rash y duración/intensidad del contacto, y comprobar IgG si exposición relevante. Solo gestante susceptible con exposición significativa requiere inmunoglobulina anti-VZV lo antes posible y hasta 10 días. La clave D puede inducir profilaxis sin exposición demostrada.","o":{"A":"Serología pareada atrasa decisiones y aciclovir no es la profilaxis universal de primera elección.","B":"Una IgG urgente es razonable, pero aciclovir no se indica automáticamente ante susceptibilidad.","C":"Serología pareada es lenta y puede demorar inmunoprofilaxis cuando hay exposición real."},"src":"CDC, Varicella-Zoster exposure and prophylaxis","src_url":"https://www.cdc.gov/chickenpox/hcp/clinical-guidance/index.html"});
Object.assign(KEY["pdf-novas-6"]["5"],{"a":"B","status":"validado","why":"La vesícula biliar, especialmente sobre cálculos y biopelículas, es reservorio clásico de Salmonella Typhi en portadores crónicos, que eliminan bacterias por vía biliar y heces.","o":{"A":"Divertículos colónicos no son el reservorio clásico de portación crónica tifoidea.","C":"Intestino delgado es zona de infección, pero portación crónica se asocia a vesícula.","D":"Intestino grueso puede contener el microorganismo, no explica el nicho de portador clásico."},"src":"CDC, Typhoid Fever Clinical Guidance","src_url":"https://www.cdc.gov/typhoid-fever/hcp/clinical-guidance/index.html"});
Object.assign(KEY["pdf-novas-6"]["6"],{"a":"D","status":"validado","why":"Bacteriemia/sepsis asociada a catéter por Staphylococcus aureus resistente a meticilina requiere antimicrobiano activo contra MRSA (p. ej., vancomicina IV o daptomicina según caso), extracción del catéter en general, hemocultivos de control y búsqueda de focos secundarios.","o":{"A":"Cefalotina no cubre MRSA y aminoglucósido no la corrige como esquema estándar.","B":"Imipenem no es activo de forma fiable contra MRSA.","C":"Ampicilina/sulbactam no cubre MRSA por resistencia a betalactámicos convencionales."},"src":"IDSA, MRSA Clinical Practice Guideline","src_url":"https://www.idsociety.org/practice-guideline/mrsa/"});
Object.assign(KEY["pdf-novas-6"]["7"],{"a":"B","status":"validado","why":"Uretritis purulenta con sospecha de gonococo/clamidia requiere diagnóstico molecular cuando sea posible y tratamiento empírico que cubra ambos: ceftriaxona IM para gonorrea y doxiciclina por 7 días si clamidia no descartada, además de manejo de parejas.","o":{"A":"Penicilina benzatínica no trata gonorrea actual de forma fiable.","C":"Espectinomicina más clindamicina no es pauta recomendada para ambas ITS.","D":"Cefixima tiene uso alternativo restringido y metronidazol no cubre clamidia."},"src":"CDC, Urethritis and Cervicitis Guidelines","src_url":"https://www.cdc.gov/std/treatment-guidelines/urethritis-and-cervicitis.htm"});
Object.assign(KEY["pdf-novas-6"]["8"],{"a":"C","status":"validado","why":"La orina sin sangre visible no se considera fluido transmisor habitual de VIH. La transmisión sexual o parenteral se asocia a fluidos como sangre, semen, secreciones vaginales/rectales y leche materna, entre otros fluidos estériles cuando hay contacto de alto riesgo.","o":{"A":"LCR se considera potencialmente infeccioso en exposición ocupacional.","B":"Secreciones vaginales son fluidos de posible transmisión sexual.","D":"Líquido pleural es fluido corporal normalmente estéril considerado potencialmente infeccioso en contexto ocupacional."},"src":"CDC, HIV Transmission","src_url":"https://www.cdc.gov/hiv/causes/index.html"});
Object.assign(KEY["pdf-novas-6"]["9"],{"a":"D","status":"validado","why":"Meningitis de predominio linfocítico, líquido claro, glucosa cercana a normal en relación con plasma y ADA baja apunta a meningitis viral, frecuentemente enterovirus, en un adulto estable. La proteína de 170 mg/dl es relativamente elevada y obliga a mantener diferencial si evolución es atípica.","o":{"A":"Meningococo suele producir pleocitosis neutrofílica y cuadro bacteriano agudo.","B":"Tuberculosis suele acompañarse de glucorraquia claramente baja y evolución subaguda; ADA baja la hace menos probable sin excluirla.","C":"Neumococo típicamente cursa meningitis bacteriana con predominio neutrofílico y menor glucorraquia."},"src":"CDC, Viral Meningitis","src_url":"https://www.cdc.gov/meningitis/about/viral-meningitis.html"});
Object.assign(KEY["pdf-novas-6"]["10"],{"a":"B","status":"discutible","why":"Una úlcera genital indurada indolora sugiere sífilis primaria; requiere test no treponémico + treponémico, tratamiento oportuno y notificación según definición de caso y sistema nacional vigente. El enunciado no precisa si exige notificación como sospechoso/probable o confirmado, y las categorías B y C son poco claras sin conocer la ficha oficial de eventos.","o":{"A":"Esperar resultados puede demorar acciones preventivas en casos clínicos probables.","C":"La categoría «sífilis temprana» puede corresponder, pero depende de la definición usada y de confirmación.","D":"«Sífilis sin especificar» puede ser incorrecta si la etapa primaria es clínicamente evidente."},"src":"Ministerio de Salud Argentina, Abordaje de la sífilis en personas adultas 2024","src_url":"https://www.argentina.gob.ar/sites/default/files/2024/04/abordaje_de_la_sifilis_en_personas_adultas_2662024_0.pdf"});
Object.assign(KEY["pdf-novas-6"]["11"],{"a":"D","status":"discutible","why":"El meningococo habitualmente provoca meningitis bacteriana purulenta, mientras causas virales, neoplásicas y VIH pueden producir LCR claro. Pero el aspecto macroscópico NO excluye meningococo, especialmente en fase inicial; la negación absoluta de la pregunta es clínicamente inapropiada.","o":{"A":"Neoplasias pueden causar meningitis crónica con LCR transparente.","B":"Virus suelen producir LCR claro y pleocitosis linfocítica.","C":"VIH puede ocasionar meningitis de líquido claro directa o asociada a coinfecciones."},"src":"CDC, Meningitis Clinical Overview","src_url":"https://www.cdc.gov/meningitis/about/index.html"});
Object.assign(KEY["pdf-novas-6"]["12"],{"a":"C","status":"validado","why":"ACLARACIÓN DE ENUNCIADO: la vacuna 23-valente es POLISACÁRIDA NO conjugada (PPSV23), a diferencia de PCV13 conjugada. Las vacunas conjugadas inducen respuesta T-dependiente y memoria inmunológica robusta; el polisacárido solo produce menor memoria inmunitaria.","o":{"A":"No se trata de tener de forma inherente más reacciones locales como distinción principal.","B":"PCV13 suele generar mejor memoria inmunológica en grupos con respuesta polisacárida limitada.","D":"Una diferencia de precio no explica el mecanismo inmunológico clave."},"src":"CDC, Pneumococcal Vaccine Recommendations","src_url":"https://www.cdc.gov/pneumococcal/hcp/vaccine-recommendations/index.html"});
Object.assign(KEY["pdf-novas-6"]["13"],{"a":"D","status":"validado","why":"Erisipela: placa eritematosa, caliente, edematosa y dolorosa con límites bien netos o sobreelevados, típicamente por estreptococos betahemolíticos, con posible fiebre.","o":{"A":"Una placa principalmente descamativa no describe la infección aguda típica.","B":"Bordes imprecisos se describen más en celulitis que en erisipela.","C":"Descamación e imprecisión de límites no son la morfología elemental característica."},"src":"IDSA, Skin and Soft Tissue Infections","src_url":"https://www.idsociety.org/practice-guideline/skin-and-soft-tissue-infections/"});
Object.assign(KEY["pdf-novas-6"]["14"],{"a":"C","status":"validado","why":"La tríada clásica de mononucleosis infecciosa es fiebre, faringoamigdalitis y linfadenopatías (frecuentemente cervicales posteriores), a veces con esplenomegalia.","o":{"A":"Exantema no es componente necesario de la tríada clásica.","B":"Hepatomegalia puede presentarse, pero falta faringitis característica.","D":"Esplenomegalia puede acompañar, pero fiebre sigue integrando tríada clásica."},"src":"CDC, About Infectious Mononucleosis","src_url":"https://www.cdc.gov/epstein-barr/about/mononucleosis.html"});
Object.assign(KEY["pdf-novas-6"]["15"],{"a":"A","status":"validado","why":"Las adenopatías supraclaviculares son siempre de mayor preocupación por malignidad u otra enfermedad sistémica y merecen valoración adecuada aun con diámetros relativamente pequeños.","o":{"B":"Región preauricular puede aumentar reactivamente por procesos oculares/ORL.","C":"Ganglios axilares de tamaño pequeño pueden ser reactivos.","D":"Ganglios inguinales pequeños son comunes por estímulos cutáneos benignos."},"src":"Merck Manual Professional, Lymphadenopathy","src_url":"https://www.merckmanuals.com/professional/cardiovascular-disorders/symptoms-of-cardiovascular-disorders/lymphadenopathy"});
Object.assign(KEY["pdf-novas-6"]["2"],{"o":{"A":"Aciclovir puede indicarse a determinados pacientes con varicela, pero no previene de forma directa sobreinfección bacteriana.","B":"Hervir ropa no sustituye cuidado de piel y uñas cortas.","D":"Evitar bañarse es contraproducente; se recomienda higiene suave de lesiones."}});
Object.assign(KEY["pdf-novas-6"]["10"],{"o":{"A":"Posponer toda notificación hasta confirmar laboratorio puede retrasar medidas de salud pública según definición de caso.","C":"La categoría sífilis sin especificar puede no ser correcta ante chancro primario claramente compatible.","D":"Control serológico es seguimiento, no evento de notificación inicial."}});

/* Validación individual: neurología, oftalmología y pediatría */
Object.assign(KEY["pdf-novas-7"]["1"],{"a":"C","status":"validado","why":"Atrofia, fasciculaciones, hipotonía e hiporreflexia sugieren lesión de MOTONEURONA INFERIOR. La distribución, reflejos y sensibilidad ayudan a diferenciar asta anterior, raíz, nervio periférico y otras causas.","o":{"A":"Motoneurona superior se caracteriza por hiperreflexia, espasticidad y signo de Babinski.","B":"CIDP suele dar neuropatía sensitivo-motora con arreflexia, pero fasciculaciones/atrofia sin datos sensitivos favorecen síndrome motoneuronal inferior como localización.","D":"Esclerosis múltiple produce habitualmente signos de vía larga o lesiones centrales, no síndrome aislado de motoneurona inferior."},"src":"Merck Manual, Exploración neurológica y síndromes motores","src_url":"https://www.merckmanuals.com/professional/neurologic-disorders"});
Object.assign(KEY["pdf-novas-7"]["2"],{"a":"D","status":"validado","why":"Disminución de necesidad de dormir, ánimo expansivo, logorrea, grandiosidad, proyectos irreales y conductas de riesgo por un mes apoyan episodio maníaco, una urgencia psiquiátrica que requiere evaluar seguridad y descartar causas orgánicas.","o":{"A":"Ansiedad generalizada no explica la grandiosidad ni disminución extrema de necesidad de sueño.","B":"Trastorno histriónico implica patrón persistente de personalidad, no episodio agudo de cambio marcado.","C":"Esquizofrenia desorganizada requiere otros criterios psicóticos; aquí predomina síndrome afectivo maníaco."},"src":"NICE CG185, Bipolar Disorder: Assessment and Management","src_url":"https://www.nice.org.uk/guidance/cg185/chapter/recommendations"});
Object.assign(KEY["pdf-novas-7"]["3"],{"a":"D","status":"discutible","why":"El término histórico «paranoia» se usa ambiguamente para delirio crónico/trastorno delirante, entidad con inicio a menudo más tardío que esquizofrenia. No es correcto afirmar mismas edades típicas, pero las categorías originales son obsoletas y la edad de inicio se solapa. Mantener sin puntuación hasta actualizar terminología.","o":{"A":"Delirios persecutorios pueden aparecer en ambos trastornos.","B":"En trastorno delirante las creencias pueden ser relativamente sistematizadas y hay mejor conservación general del funcionamiento.","C":"Desorganización formal y síntomas negativos pueden ser más evidentes en esquizofrenia que en trastorno delirante."},"src":"NICE CG185, Bipolar Disorder: Assessment and Management","src_url":"https://www.nice.org.uk/guidance/cg185/chapter/recommendations"});
Object.assign(KEY["pdf-novas-7"]["4"],{"a":"A","status":"validado","why":"Cefalea intensa y alteraciones visuales con PA 220/110 exigen buscar daño de órgano diana, incluida emergencia hipertensiva y hemorragia intracraneal. Entre las opciones, TC encefálica sin contraste es la más adecuada para descartar sangrado agudo, junto a fondo de ojo, examen neurológico y valoración cardíaca/renal; no esperar solo reposo.","o":{"B":"Punción lumbar sin descartar lesión intracraneal y sin indicación específica es peligrosa.","C":"Fondo de ojo es importante para retinopatía hipertensiva, pero no excluye hemorragia cerebral aguda.","D":"Observación sin evaluación urgente omite posible daño de órgano blanco."},"src":"ACEP, Clinical Policy: Acute Headache","src_url":"https://www.acep.org/patient-care/clinical-policies/acute-headache"});
Object.assign(KEY["pdf-novas-7"]["5"],{"a":"B","status":"validado","why":"El VII par posee fibras parasimpáticas relacionadas con núcleo salivatorio superior, incluidas neuronas destinadas a glándula lagrimal (núcleo lagrimal).","o":{"A":"El núcleo salivatorio inferior se asocia al glosofaríngeo IX.","C":"Edinger-Westphal pertenece al III par, no al VII.","D":"Núcleo motor dorsal es del vago X."},"src":"Merck Manual, Exploración neurológica y síndromes motores","src_url":"https://www.merckmanuals.com/professional/neurologic-disorders"});
Object.assign(KEY["pdf-novas-7"]["6"],{"a":"D","status":"discutible","why":"Ácido tióctico (alfa-lipoico) no es primera línea con evidencia clínica sólida para dolor de polineuropatía ALCOHÓLICA. Debe optimizarse pregabalina según dosis/función renal y considerar duloxetina o antidepresivo tricíclico, además de abstinencia de alcohol y evaluación nutricional. Ninguna alternativa representa claramente el siguiente paso basado en guías.","o":{"A":"Paracetamol no es fármaco dirigido al dolor neuropático intenso.","B":"Carbamazepina tiene uso principal en neuralgia trigeminal y no es primera elección general.","C":"Codeína/opioides no son primera elección rutinaria para dolor neuropático crónico."},"src":"NICE CG173, Neuropathic pain pharmacological treatment","src_url":"https://www.nice.org.uk/guidance/cg173/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-7"]["7"],{"a":null,"status":"discutible","why":"GABARITO ORIGINAL C ERRÓNEO: gabapentina prácticamente no se metaboliza en hígado y se elimina sin cambios por riñón; en insuficiencia renal puede acumularse con sedación, ataxia o mioclonías. No se considera nefrotóxico directo ni hepatotóxico típico. La opción B confunde acumulación renal con toxicidad renal; ninguna alternativa es precisa.","o":{"A":"No es efecto adverso principal un infarto de miocardio.","B":"La eliminación renal exige ajuste de dosis ante deterioro del filtrado, pero no es «toxicidad renal» en sentido de lesión renal directa.","C":"Hepatotoxicidad no es el riesgo esperado de gabapentina pese a antecedente de alcohol.","D":"Lesión cerebral estructural no es toxicidad característica; puede existir depresión SNC con alcohol."},"src":"FDA, Neurontin gabapentin prescribing information","src_url":"https://www.accessdata.fda.gov/drugsatfda_docs/label/2020/020235s068%2C020882s049%2C021129s049lbl.pdf"});
Object.assign(KEY["pdf-novas-7"]["8"],{"a":"B","status":"validado","why":"Cefalea recurrente unilateral pulsátil, intensa, asociada a náuseas, fotofobia y sin síntomas neurológicos precedentes es compatible con migraña SIN aura, siempre tras evaluar señales de alarma.","o":{"A":"Cefalea tensional suele ser opresiva bilateral, no se agrava con actividad y no tiene náuseas prominentes.","C":"La cefalea en racimos tiene dolor orbitario unilateral con síntomas autonómicos y ataques breves.","D":"Migraña con aura exige síntomas neurológicos reversibles típicos, no descritos."},"src":"ICHD-3, Migraine without Aura","src_url":"https://ichd-3.org/1-migraine/1-1-migraine-without-aura/"});
Object.assign(KEY["pdf-novas-7"]["9"],{"a":"D","status":"validado","why":"Isquemia de circulación vertebrobasilar afecta estructuras centrales de tronco encefálico y cerebelo, por lo que puede provocar vértigo CENTRAL, a menudo con ataxia o signos neurológicos asociados.","o":{"A":"Vértigo postraumático es con frecuencia vestibular periférico, p. ej., VPPB posterior a trauma.","B":"Cinetosis es respuesta vestibular a movimiento, no lesión central vascular.","C":"Laberintitis es causa vestibular periférica."},"src":"Merck Manual, Exploración neurológica y síndromes motores","src_url":"https://www.merckmanuals.com/professional/neurologic-disorders"});
Object.assign(KEY["pdf-novas-8"]["1"],{"a":"B","status":"validado","why":"Midriasis describe una pupila dilatada, habitualmente de diámetro mayor a 5 mm; debe evaluarse reactividad a luz, asimetría y contexto del traumatismo, ya que anisocoria fija puede ser dato de herniación.","o":{"A":"Pupila de 2–5 mm suele estar en intervalo normal según luz ambiental.","C":"Miosis corresponde a pupila pequeña, no dilatada.","D":"Ausencia de reflejo fotomotor puede coexistir con midriasis, pero no la define por sí sola."},"src":"AAO EyeWiki, Neuro-Ophthalmology and Visual Fields","src_url":"https://eyewiki.aao.org/Neuro-Ophthalmology"});
Object.assign(KEY["pdf-novas-8"]["2"],{"a":"C","status":"validado","why":"Hemianopsia bitemporal resulta de lesión del QUIASMA óptico, donde cruzan fibras de hemirretinas nasales; pensar en compresión selar (p. ej., macroadenoma hipofisario).","o":{"A":"Lesión de nervio óptico derecho causa pérdida visual monocular derecha.","B":"Lesión de tracto óptico izquierdo causa hemianopsia homónima derecha.","D":"Lesión de corteza calcarina genera defectos homónimos contralaterales."},"src":"AAO EyeWiki, Neuro-Ophthalmology and Visual Fields","src_url":"https://eyewiki.aao.org/Neuro-Ophthalmology"});
Object.assign(KEY["pdf-novas-9"]["1"],{"a":"B","status":"validado","why":"CORRECCIÓN DE GABARITO A → B: después de la pérdida fisiológica inicial y recuperación de peso al nacer, un lactante de término sano suele ganar aproximadamente 20–30 g por día durante el primer mes, sin diferencias rígidas de 12 g niña y 15 g varón como señalaba A.","o":{"A":"12–15 g/día es inferior al incremento promedio esperado para un recién nacido sano ya alimentándose.","C":"40–50 g/día supera el promedio habitual y no es meta universal.","D":"El peso no permanece constante después del descenso fisiológico inicial."},"src":"HealthyChildren / AAP, Your Baby's First Month","src_url":"https://www.healthychildren.org/English/ages-stages/baby/Pages/First-Month-Physical-Appearance-and-Growth.aspx"});
Object.assign(KEY["pdf-novas-9"]["2"],{"a":"A","status":"validado","why":"Toxoplasmosis congénita clásica: coriorretinitis, hidrocefalia y calcificaciones intracraneales difusas; convulsiones también pueden presentarse. La opción A recoge el cuadro históricamente conocido como tétrada de Sabin (la tríada de Sabin es más clásica).","o":{"B":"Sordera y microcefalia pueden aparecer en infecciones congénitas diferentes; no define toxoplasmosis.","C":"Cardiopatía, catarata y sordera son hallazgos clásicos de rubéola congénita.","D":"Ictericia, hepatoesplenomegalia y petequias pueden ocurrir en CMV u otras TORCH y no forman la tríada típica de toxoplasmosis."},"src":"CDC, Clinical Overview of Toxoplasmosis","src_url":"https://www.cdc.gov/toxoplasmosis/hcp/clinical-overview/index.html"});
Object.assign(KEY["pdf-novas-9"]["3"],{"a":"D","status":"validado","why":"A los 8 meses es común ansiedad de separación del desarrollo. Los objetos de apego, despedidas breves predecibles y cuidador conocido son intervenciones razonables para facilitar adaptación.","o":{"A":"Objeto transicional puede ayudar, pero no es la única recomendación.","B":"Despedida breve y serena ayuda, pero también es importante continuidad del cuidador.","C":"Cuidador confiable y predecible es importante, pero las medidas no se excluyen."},"src":"HealthyChildren / AAP, Separation Anxiety","src_url":"https://www.healthychildren.org/English/ages-stages/toddler/Pages/Soothing-Your-Childs-Separation-Anxiety.aspx"});
Object.assign(KEY["pdf-novas-9"]["4"],{"a":null,"status":"discutible","why":"PREGUNTA CLÍNICAMENTE INSEGURA: lactante de cinco meses con tiraje y SpO2 89% sugiere bronquiolitis hipóxica hasta demostrar otra causa. Requiere oxígeno titulado, vigilancia y soporte respiratorio/hidratación, con posible internación. La guía NICE/AAP desaconseja salbutamol, corticoides y nebulizaciones beta2 rutinarias en bronquiolitis. TODAS las opciones incluyen β2 y algunas corticoides: ninguna alternativa describe correctamente el manejo.","o":{"A":"Contiene oxígeno apropiado, pero salbutamol seriado no es tratamiento de rutina en bronquiolitis.","B":"Dexametasona IM y salbutamol rutinarios no están indicados.","C":"Hidrocortisona IV y salbutamol seriado no están indicados.","D":"Prednisona y salbutamol seriado no están indicados."},"src":"NICE NG9, Bronchiolitis in children","src_url":"https://www.nice.org.uk/guidance/ng9/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-9"]["5"],{"a":"B","status":"validado","why":"En faringitis por estreptococo A tratada con antibióticos apropiados dentro de los primeros nueve días del inicio de síntomas, se previene de modo eficaz fiebre reumática aguda; no se debe retrasar innecesariamente terapia tras test positivo.","o":{"A":"17 días supera el período de prevención primaria clásico.","C":"Dos días no son límite máximo requerido para prevenir fiebre reumática.","D":"Cuatro días también es ventana válida, pero no el máximo reconocido."},"src":"CDC, Group A Streptococcal Pharyngitis Clinical Guidance","src_url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/strep-throat.html"});
Object.assign(KEY["pdf-novas-9"]["6"],{"a":"B","status":"validado","why":"Ronquidos, pausas respiratorias, despertares, somnolencia diurna e hipertrofia amigdalina sugieren síndrome de apnea obstructiva del sueño pediátrica, confirmado mediante polisomnografía nocturna.","o":{"A":"Ecocardiograma evalúa repercusiones cardíacas, no confirma eventos apneicos.","C":"Espirometría no caracteriza pausas respiratorias nocturnas.","D":"Endoscopia puede definir anatomía obstructiva, pero no cuantifica apnea e hipopnea durante sueño."},"src":"AAP, Childhood obstructive sleep apnea clinical practice guideline","src_url":"https://publications.aap.org/pediatrics/article/130/3/e714/30231/Diagnosis-and-Management-of-Childhood-Obstructive"});
Object.assign(KEY["pdf-novas-9"]["7"],{"a":"A","status":"discutible","why":"Ante neumonía con falta de mejoría y matidez basal, lo primero es sospechar DERRAME PARANEUMÓNICO y confirmarlo con ecografía pleural. Empiema es líquido purulento o infectado y requiere datos de líquido/imágenes; no se puede concluir empiema solo por matidez. Entre alternativas A es complicación posible, pero falta la más inmediata «derrame parapneumónico».","o":{"B":"Empiema puede complicar derrame, pero no se confirma por percusión sola.","C":"Neumonía necrotizante requiere hallazgos imagenológicos específicos.","D":"Fístula broncopleural suele aparecer en enfermedad necrosante complicada."},"src":"BTS, Paediatric Pleural Infection guideline","src_url":"https://thorax.bmj.com/content/60/suppl_1/i1"});
Object.assign(KEY["pdf-novas-9"]["8"],{"a":"D","status":"validado","why":"La atención inicial de convulsión activa incluye seguridad, evaluación ABC, decúbito lateral, oxígeno si precisa, glucemia capilar y búsqueda de causas inmediatas. Si la convulsión persiste ≥5 minutos o hay crisis recurrentes sin recuperación, administrar benzodiazepina sin demoras.","o":{"A":"Suero glucosado empírico en todos y posición semisentada no son medidas estándar.","B":"Benzodiazepina no es obligatoria antes de cinco minutos para toda crisis aislada; sí cuando dura ≥5 min o se repite sin recuperación.","C":"Diazepam IM no es la vía preferida ni se indica sin valoración inicial."},"src":"NICE NG217, Epilepsies in children, young people and adults","src_url":"https://www.nice.org.uk/guidance/ng217/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-9"]["9"],{"a":"C","status":"validado","why":"Cianosis diferencial (piernas cianóticas con extremidades superiores rosadas) se observa en ductus arterioso persistente con inversión del cortocircuito por hipertensión pulmonar Eisenmenger, cuando flujo desaturado entra a aorta descendente distal al nacimiento de vasos braquiocefálicos.","o":{"A":"Tetralogía de Fallot suele causar cianosis generalizada, no limitada a miembros inferiores.","B":"Coartación puede reducir pulsos/presión en piernas, pero no produce típicamente esta saturación diferencial sin otro defecto.","D":"CIV con hipertensión pulmonar tiende a cianosis sistémica al invertir shunt, sin patrón diferencial típico."},"src":"American Heart Association, Congenital Heart Defects","src_url":"https://www.heart.org/en/health-topics/congenital-heart-defects"});
Object.assign(KEY["pdf-novas-9"]["10"],{"a":"D","status":"validado","why":"Regurgitación gastroesofágica fisiológica del lactante alcanza máxima frecuencia alrededor de 3–4 meses y tiende a resolverse espontáneamente entre los 12 y 24 meses, si curva ponderal normal y sin señales de alarma.","o":{"A":"Pico a 8 meses y resolución 24–36 es tardío frente evolución habitual.","B":"Pico a 2 meses se aleja del patrón típico.","C":"Pico a 6 meses y resolución 24–36 sobrestima tiempo habitual de persistencia."},"src":"NICE NG1, GOR and GORD in children and young people","src_url":"https://www.nice.org.uk/guidance/ng1/chapter/recommendations"});
Object.assign(KEY["pdf-novas-9"]["11"],{"a":"B","status":"validado","why":"Hidropesía fetal y anemia grave asociadas a contacto familiar con enfermedad exantemática de mejillas abofeteadas son característicos de parvovirus B19 (eritema infeccioso o quinta enfermedad).","o":{"A":"Escarlatina por estreptococo no es causa típica de aplasia fetal severa.","C":"Varicela congénita causa otros patrones de malformación/infección.","D":"Sarampión no explica la asociación clásica con anemia fetal e hidrops."},"src":"CDC, About Parvovirus B19","src_url":"https://www.cdc.gov/parvovirus-b19/about/index.html"});
Object.assign(KEY["pdf-novas-9"]["12"],{"a":"A","status":"validado","why":"Fractura diafisaria de clavícula en niño de 7 años se trata habitualmente de forma conservadora: cabestrillo (más cómodo) o vendaje en ocho; entre las opciones, A es una inmovilización no quirúrgica posible, aunque hoy suele preferirse cabestrillo.","o":{"B":"Yeso circunferencial no es inmovilización habitual de clavícula.","C":"Aunque consolide bien, requiere analgesia e inmovilización inicial.","D":"Férula de abducción no es tratamiento estándar de fractura clavicular."},"src":"Hull NHS, Emergency Care: Paediatric Fracture of the Clavicle","src_url":"https://www.hey.nhs.uk/patient-leaflet/emergency-care-paediatric-fracture-of-the-clavicle-collar-bone/"});
Object.assign(KEY["pdf-novas-9"]["13"],{"a":"A","status":"validado","why":"Un resultado virológico negativo a 1 mes en lactante expuesto a VIH no excluye infección de manera definitiva. Se repite test virológico (ADN/ARN VIH) a 1–2 meses según algoritmo y nuevamente a 4–6 meses; se considera cronología de profilaxis y lactancia.","o":{"B":"Serología convencional a 6 meses puede reflejar anticuerpos maternos y no reemplaza prueba virológica temprana.","C":"Serología a 10 meses no es el siguiente estudio oportuno.","D":"PCR recién a 18 meses retrasa diagnóstico; a esa edad pueden emplearse también pruebas serológicas."},"src":"NIH, Diagnosis of HIV Infection in Infants and Children 2026","src_url":"https://clinicalinfo.hiv.gov/en/guidelines/pediatric-arv/diagnosis-hiv-infection-infants-and-children"});
Object.assign(KEY["pdf-novas-9"]["14"],{"a":"A","status":"validado","why":"12 kg × 100 mg/kg/día = 1.200 mg/día; dividido en tres dosis = 400 mg cada 8 h. Amoxicilina 500 mg/5 mL = 100 mg/mL; cada dosis corresponde a 4 mL. Siempre confirmar concentración real del frasco y método de administración.","o":{"B":"5 mL aportan 500 mg cada 8 horas, total 1.500 mg/día.","C":"4 mL cada seis horas sumarían 1.600 mg/día, por encima de pauta indicada.","D":"5 mL cada seis horas sumarían 2.000 mg/día."},"src":"WHO, Pocket Book of Hospital Care for Children","src_url":"https://www.who.int/publications/i/item/9789241548373"});
Object.assign(KEY["pdf-novas-9"]["15"],{"a":"D","status":"validado","why":"Talla baja, cuello corto/alado, tórax ancho con pezones separados, nevos y ausencia de pubertad orientan a síndrome de Turner (45,X o mosaicismos); requiere cariotipo y evaluación cardíaca/renal.","o":{"A":"Déficit aislado de hormona de crecimiento no explica estigmas somáticos típicos.","B":"Celiaquía puede causar talla baja pero no suele producir fenotipo de Turner.","C":"Noonan comparte rasgos, pero suele afectar ambos sexos y requiere otros elementos; Turner es más probable."},"src":"MedlinePlus, Turner syndrome","src_url":"https://medlineplus.gov/genetics/condition/turner-syndrome/"});
Object.assign(KEY["pdf-novas-9"]["16"],{"a":"C","status":"validado","why":"Masa escrotal indolora del cordón superior al testículo que disminuye en decúbito sugiere varicocele, dilatación venosa del plexo pampiniforme, confirmable por examen de pie con Valsalva y eco Doppler si es necesario. CORRECCIÓN del gabarito A → C.","o":{"A":"Hidrocele suele ser líquido alrededor del testículo, fluctúa/transilumina y no disminuye tan característicamente con decúbito.","B":"Tumor testicular suele palparse como masa intratesticular sólida persistente.","D":"Quiste de Morgagni es estructura apendicular, no masa venosa que reduce en decúbito."},"src":"Merck Manual, Scrotal masses and varicocele","src_url":"https://www.merckmanuals.com/professional/genitourinary-disorders"});
Object.assign(KEY["pdf-novas-9"]["17"],{"a":"A","status":"discutible","why":"Duchenne es distrofia ligada al cromosoma X recesiva: si la madre es portadora, transmite variante a la mitad de los hijos varones. Sin embargo una proporción importante son mutaciones de novo; el diagnóstico del niño NO demuestra que la madre sea portadora, de modo que la afirmación categórica A no es segura sin estudio genético.","o":{"B":"Transmisión paterna a hijo varón no se espera para trastorno ligado al X.","C":"Ambos padres no necesitan transmitir una variante para un hijo con Duchenne.","D":"Si la madre fuera portadora, el riesgo por embarazo de varón sería cerca del 50%, no 100%."},"src":"MedlinePlus, Duchenne muscular dystrophy","src_url":"https://medlineplus.gov/genetics/condition/duchenne-and-becker-muscular-dystrophy/"});
Object.assign(KEY["pdf-novas-9"]["18"],{"a":"B","status":"validado","why":"La hernia umbilical infantil asintomática suele cerrar sola en primeros años; la reparación electiva se considera habitualmente alrededor de 4–5 años si persiste. B es la única opción cercana, aunque «3 años» puede ser precoz.","o":{"A":"Estrangulación es infrecuente; no hace falta cirugía urgente en toda hernia asintomática.","C":"La edad de colocación de prótesis no determina indicación, y generalmente no se requiere malla.","D":"Vómitos febriles inespecíficos no justifican cirugía de hernia umbilical sin signos de incarceración."},"src":"HealthyChildren, Umbilical Hernia in Babies and Children","src_url":"https://www.healthychildren.org/English/health-issues/conditions/abdominal/Pages/umbilical-hernia-in-children.aspx"});
Object.assign(KEY["pdf-novas-9"]["19"],{"a":"B","status":"validado","why":"Dermatitis irritativa del pañal afecta superficies convexas glúteas/perineales y suele RESPETAR pliegues inguinales; candidiasis del pañal suele comprometer pliegues y añadir pápulas satélite.","o":{"A":"Psoriasis del pañal puede afectar pliegues y no tiene este patrón predominante.","C":"Dermatitis seborreica suele afectar pliegues y otras zonas seborreicas.","D":"Impétigo produce lesiones infectadas con costras o ampollas, no patrón irritativo típico."},"src":"American Academy of Dermatology, Diaper Rash","src_url":"https://www.aad.org/public/everyday-care/skin-care-basics/care/diaper-rash"});
Object.assign(KEY["pdf-novas-9"]["20"],{"a":"B","status":"discutible","why":"Enfermedades médicamente inexplicables que aparecen solo con un cuidador y desaparecen sin él despiertan sospecha de trastorno facticio impuesto a otro (antiguo Munchausen por poderes), una forma de maltrato infantil. NO puede confirmarse por viñeta y requiere proteger al niño, evaluación interdisciplinaria y notificación según normativa; B es propuesta, no diagnóstico definitivo.","o":{"A":"No se explica solo por dificultades de comprensión de los cuidadores.","C":"Trastorno facticio impuesto a otro es hipótesis importante, sin presuponer culpabilidad sin evaluación.","D":"Maltrato infantil es categoría amplia que incluye esta presentación y otras causas."},"src":"NICE CG89, Child Maltreatment: When to suspect","src_url":"https://www.nice.org.uk/guidance/cg89/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-9"]["7"],{"o":{"B":"Neumonía necrotizante requiere hallazgos imagenológicos específicos; no se deduce de matidez basal.","C":"Fístula broncopleural suele aparecer en enfermedad necrosante complicada.","D":"Neumatocele es cavidad aérea, no explica matidez por líquido pleural."}});
Object.assign(KEY["pdf-novas-9"]["20"],{"o":{"A":"No se explica solo por dificultades de comprensión de cuidadores.","C":"Maltrato infantil es categoría amplia que incluye este cuadro y otros mecanismos.","D":"Iatrogenia debe considerarse, pero la correlación con presencia del cuidador aumenta sospecha de enfermedad inducida."}});

/* Validación científica: nefrología, respiratorio, reumatología, toxicología */
Object.assign(KEY["pdf-novas-10"]["1"],{"a":"A","status":"validado","why":"El túbulo proximal reabsorbe cerca de 60–70% de sodio y cloruro filtrados; la rama ascendente gruesa reabsorbe ~25% del sodio, mientras ramas distales recuperan cantidades menores.","o":{"B":"Rama descendente fina es muy permeable al agua y poco al NaCl.","C":"Rama ascendente gruesa reabsorbe cerca de un cuarto, no la mayoría del sodio.","D":"Túbulo distal maneja una proporción mucho menor de la carga filtrada."},"src":"KDIGO Clinical Practice Guideline for CKD, 2024","src_url":"https://kdigo.org/wp-content/uploads/2024/03/KDIGO-2024-CKD-Guideline.pdf"});
Object.assign(KEY["pdf-novas-10"]["2"],{"a":"D","status":"validado","why":"Fiebre, exantema, eosinofilia, artralgias y deterioro renal tras introducir fármacos, con leucocituria y proteinuria no nefrótica, sugieren NEFRITIS INTERSTICIAL AGUDA medicamentosa. Eosinofiluria no es sensible ni específica; valorar suspensión del fármaco y pruebas según contexto.","o":{"A":"Necrosis tubular aguda por tóxicos no suele causar síndrome sistémico de hipersensibilidad.","B":"Ateroembolismo suele seguir intervenciones vasculares, con signos cutáneos y eosinofilia, no este contexto farmacológico.","C":"Trombosis arterial renal suele dar dolor, isquemia y alteración renal abrupta sin exantema alérgico típico."},"src":"Merck Manual, Tubulointerstitial Nephritis","src_url":"https://www.merckmanuals.com/professional/genitourinary-disorders/tubulointerstitial-diseases/tubulointerstitial-nephritis"});
Object.assign(KEY["pdf-novas-10"]["3"],{"a":"C","status":"validado","why":"Hematuria macroscópica INDOLORA en hombre de 60 años obliga a descartar cáncer urotelial de vejiga mediante evaluación urológica, cistoscopia e imágenes apropiadas. No basta atribuirla a próstata.","o":{"A":"Hiperplasia prostática puede causar hematuria, pero no debe asumirse sin excluir neoplasia.","B":"Carcinoma de próstata tiene presentación usualmente distinta; vejiga es el principal tumor por descartar.","D":"Litiasis renal suele provocar cólico y puede dar hematuria, pero puede ser indolora ocasionalmente."},"src":"American Urological Association, Hematuria guideline","src_url":"https://www.auanet.org/guidelines-and-quality/guidelines/microhematuria"});
Object.assign(KEY["pdf-novas-10"]["4"],{"a":"D","status":"validado","why":"Lesiones purpúricas/«dedos azules» y falla renal subaguda 3 semanas tras cateterismo indican ateroembolismo por cristales de colesterol, clásico después de manipulación vascular.","o":{"A":"HTA grave puede contribuir a daño renal, pero no explica temporalidad y dedos azules típicos.","B":"Nefropatía por contraste aparece habitualmente a los 2–5 días, no después de 3 semanas con púrpura.","C":"Glomerulonefritis rápidamente progresiva no explica la asociación vascular/dermatológica postcateterismo."},"src":"Merck Manual, Renal Atheroembolism","src_url":"https://www.merckmanuals.com/professional/genitourinary-disorders/renal-vascular-disorders/renal-atheroembolism"});
Object.assign(KEY["pdf-novas-10"]["5"],{"a":"D","status":"validado","why":"Hematuria glomerular, oliguria, HTA y edema 2 semanas después de faringitis apoyan síndrome nefrítico por glomerulonefritis postestreptocócica; confirmar con C3, ASO/anti-DNasa B, sedimento y función renal, además de evaluación urgente por HTA severa.","o":{"A":"Nefropatía IgA se presenta típicamente durante infección o 1–2 días después, no 15 días.","B":"Cilindros o hematíes dismórficos orientan a origen glomerular, no urológico.","C":"No hay indicios para suponer primariamente enfermedad secundaria sistémica distinta antes del diferencial postinfeccioso."},"src":"KDIGO, Glomerular Diseases 2021","src_url":"https://kdigo.org/guidelines/gd/"});
Object.assign(KEY["pdf-novas-11"]["1"],{"a":"B","status":"validado","why":"NAC ambulatoria en paciente estable con diabetes y comorbilidades: una fluoroquinolona respiratoria (levofloxacina, dosis ajustada) es monoterapia aceptada; alternativa habitual es amoxicilina-clavulanato + macrólido o doxiciclina. Valorar riesgos de FQ, resistencia y recomendaciones locales.","o":{"A":"Macrólido solo no es opción general preferida en comórbidos por resistencia neumocócica.","C":"Amoxicilina-clavulanato solo puede no ofrecer cobertura adecuada de agentes atípicos según guía usada.","D":"Ceftriaxona intramuscular aislada no es esquema ambulatorio de primera elección de este perfil."},"src":"ATS/IDSA, Community-acquired Pneumonia treatment","src_url":"https://eguideline.guidelinecentral.com/i/1194279-community-acquired-pneumonia-in-adults/5"});
Object.assign(KEY["pdf-novas-11"]["2"],{"a":"B","status":"validado","why":"Rinosinusitis bacteriana aguda se sospecha ante síntomas persistentes ≥10 días sin mejoría, empeoramiento bifásico o comienzo severo con fiebre alta y secreción purulenta/dolor facial sostenidos.","o":{"A":"A los cinco días muchos cuadros aún son virales.","C":"Ocho días de dolor facial sin otros criterios no bastan para definir origen bacteriano.","D":"Sí existe un patrón clínico que permite sospechar bacteriana sin confirmar por cultivo rutinario."},"src":"CDC, Outpatient Clinical Care for Adults (sinusitis)","src_url":"https://www.cdc.gov/antibiotic-use/hcp/clinical-care/adult-outpatient.html"});
Object.assign(KEY["pdf-novas-11"]["3"],{"a":"A","status":"validado","why":"Tos prolongada, adelgazamiento, sudoración nocturna y hacinamiento sugieren tuberculosis pulmonar: se solicitan radiografía de tórax y muestras respiratorias para baciloscopia, prueba molecular rápida y cultivo; hemograma complementario. A es la más próxima entre opciones.","o":{"B":"Broncoscopia no es primera opción si puede obtenerse esputo adecuado.","C":"TC con contraste no sustituye la radiografía y microbiología inicial habitual.","D":"PPD no confirma TBC activa; broncoscopia no es método inicial universal."},"src":"CDC, Clinical and Laboratory Diagnosis for Tuberculosis","src_url":"https://www.cdc.gov/tb/hcp/diagnosis/index.html"});
Object.assign(KEY["pdf-novas-11"]["4"],{"a":"C","status":"discutible","why":"Edema facial/cervical y mediastino ensanchado en paciente con cáncer sugieren síndrome de vena cava superior. Urge evaluar vía aérea, hemodinamia y TC contrastada; en obstrucción grave puede ser necesario stent, radioterapia o tratamiento sistémico según tipo tumoral. Corticoides y radioterapia inmediata no son universales; C es una alternativa histórica condicionada por gravedad.","o":{"A":"Resonancia y biopsia antes de toda estabilización pueden demorar tratamiento en paciente comprometido.","B":"Radioterapia puede estar indicada, pero no antes de evaluar urgencia y etiología cuando no hay amenaza vital.","D":"TC y terapia urgente pueden ser apropiadas, pero esteroide/RT no se indican de forma idéntica en todos los casos."},"src":"NCI, Superior Vena Cava Syndrome (PDQ)","src_url":"https://www.cancer.gov/about-cancer/treatment/side-effects/cardiopulmonary-pdq"});
Object.assign(KEY["pdf-novas-11"]["5"],{"a":"A","status":"validado","why":"En reagudización de EPOC debe TITULARSE el oxígeno si hay hipoxemia, generalmente a saturación 88–92%, evitando administrar FiO2 alta al 50% indiscriminadamente por riesgo de hipercapnia y acidosis.","o":{"B":"Corticoides sistémicos en cursos cortos benefician exacerbaciones moderadas-graves.","C":"Antibióticos se indican si hay signos de infección bacteriana, sobre todo cambios de esputo/purulencia o ventilación.","D":"Broncodilatadores de acción corta, incluido ipratropio, se usan en exacerbación."},"src":"Australian Commission on Safety and Quality in Health Care, COPD Clinical Care Standard","src_url":"https://www.safetyandquality.gov.au/standards/clinical-care-standards/chronic-obstructive-pulmonary-disease-clinical-care-standard"});
Object.assign(KEY["pdf-novas-11"]["6"],{"a":"A","status":"validado","why":"La espirometría NO es estudio útil para confirmar/excluir embolia pulmonar aguda. Según probabilidad y estabilidad se utilizan angio-TC, gammagrafía V/Q, dímero D en preprobabilidad baja/intermedia y ecocardiografía en inestabilidad/estratificación.","o":{"B":"Dímero D en probabilidad baja-intermedia puede ayudar a excluir TEP según umbral apropiado.","C":"Centellograma V/Q es alternativa de diagnóstico cuando angio-TC no se puede usar.","D":"Ecocardiografía valora función ventricular derecha y ayuda en pacientes inestables."},"src":"AHA/ACC and multisociety guideline 2026, Acute Pulmonary Embolism","src_url":"https://www.jacc.org/doi/10.1016/j.jacc.2025.11.005"});
Object.assign(KEY["pdf-novas-11"]["7"],{"a":"C","status":"discutible","why":"Sospecha de TEP de alto riesgo con presión sistólica 70 mmHg exige resucitación inmediata, anticoagulación apropiada y evaluación rápida de reperfusión (trombólisis si procede). La angio-TC confirma si el traslado es seguro; si no, ecocardiografía a pie de cama puede sostener decisión. C fuerza TC en paciente con shock sin especificar estabilidad de transporte.","o":{"A":"Dímero D no es prueba de confirmación y no debe atrasar manejo en shock.","B":"HBPM sin más estudios/reperfusión puede ser insuficiente en TEP de alto riesgo; a menudo se prefiere heparina no fraccionada.","D":"La angio-TC es apropiada solo si se puede hacer sin riesgo ni demoras; alternativa eco a pie de cama."},"src":"AHA/ACC and multisociety guideline 2026, Acute Pulmonary Embolism","src_url":"https://www.jacc.org/doi/10.1016/j.jacc.2025.11.005"});
Object.assign(KEY["pdf-novas-11"]["8"],{"a":null,"status":"discutible","why":"Pregunta insegura: inmunodeficiencia celular con CD4 bajos e infiltrado DIFUSO obliga a considerar neumonía por Pneumocystis jirovecii, especialmente con hipoxemia, además de tuberculosis miliar y otras infecciones oportunistas. Pneumocystis no figura entre opciones, y TBC no puede sostenerse como primer diagnóstico único sin contexto epidemiológico y pruebas.","o":{"A":"Bacilos gramnegativos pueden dar neumonía, pero no son la asociación más característica con CD4 bajos e infiltrado difuso.","B":"Aspergiloma forma masa intracavitaria y no explica infiltrado difuso de esta presentación.","C":"TBC diseminada puede generar patrón miliar, pero requiere imagen/estudios específicos.","D":"Linfangitis carcinomatosa no se deduce del déficit de inmunidad celular."},"src":"NIH, Pneumocystis Pneumonia Opportunistic Infections","src_url":"https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-adult-and-adolescent-opportunistic-infections/pneumocystis-pneumonia"});
Object.assign(KEY["pdf-novas-11"]["9"],{"a":"C","status":"validado","why":"Imposibilidad para hablar, agitación y TÓRAX SILENTE en crisis asmática severa son signos de amenaza vital y fracaso ventilatorio inminente; se requiere equipo de cuidados críticos, broncodilatación intensiva, corticoides IV/orales y preparación para intubación/ventilación, que puede ser inmediata si deteriora.","o":{"A":"Esperar gasometría antes de tratamiento retrasa maniobras salvadoras.","B":"Salbutamol continuo forma parte del tratamiento, pero puede ser insuficiente si fallo respiratorio inminente.","D":"Corticoides son necesarios, pero su inicio de acción es tardío y no reemplaza soporte ventilatorio."},"src":"GINA 2026 Summary Guide, asthma exacerbations","src_url":"https://ginasthma.org/wp-content/uploads/2026/07/GINA-Summary-Guide-2026-WEB-WMS.pdf"});
Object.assign(KEY["pdf-novas-11"]["10"],{"a":"D","status":"validado","why":"Debilidad neuromuscular y disfagia con hipoventilación (PCO2 48), hipoxemia y atelectasias basales indican hipoventilación alveolar más desajuste ventilación/perfusión como mecanismos de alteración gaseosa.","o":{"A":"No existe antecedente de FiO2 reducida; hipoventilación es el mecanismo evidente.","B":"Difusión alterada aislada suele no causar retención de CO2 inicial importante.","C":"La FiO2 ambiental normal no explica hipercapnia ni atelectasias."},"src":"ATS/ERS Standardization of Spirometry 2019","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6794117/"});
Object.assign(KEY["pdf-novas-11"]["11"],{"a":"C","status":"discutible","why":"El tabaquismo causa tempranamente disfunción mucociliar y alteración de pequeñas vías aéreas; el descenso en parámetros de vías distales puede ser detectable antes de FEV1 obstructivo establecido, pero no está bien definida una «primera alteración» única reversible. C y D son parcialmente defendibles según medida usada.","o":{"A":"Tos es síntoma, no prueba funcional precoz objetiva específica.","B":"Expectoración tampoco define primera alteración demostrable.","D":"Obstrucción de vías distales puede ocurrir de manera temprana, pero no excluye daño ciliar anterior."},"src":"USPSTF, Tobacco Smoking Cessation in Adults","src_url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/tobacco-use-in-adults-and-pregnant-women-counseling-and-interventions"});
Object.assign(KEY["pdf-novas-11"]["12"],{"a":"C","status":"validado","why":"La otitis externa aguda difusa sin complicaciones se maneja con limpieza del conducto cuando es segura, gotas antibióticas/antisépticas tópicas según integridad timpánica, y analgésicos sistémicos; no son necesarios antibióticos VO de rutina.","o":{"A":"Cirugía no es tratamiento inicial de otitis externa difusa simple.","B":"Antibióticos orales no son primera elección sin extensión a tejidos vecinos o inmunosupresión.","D":"Gotas tópicas son apropiadas, pero no contemplan aseo y control del dolor cuando necesario; C es más completa."},"src":"AAO-HNS, Acute Otitis Externa Clinical Practice Guideline","src_url":"https://www.entnet.org/quality-practice/quality-products/clinical-practice-guidelines/acute-otitis-externa/"});
Object.assign(KEY["pdf-novas-11"]["13"],{"a":"B","status":"discutible","why":"La radiografía torácica en espiración se enseñaba históricamente para detectar neumotórax pequeño, pero la evidencia radiológica actual no muestra mayor sensibilidad que una radiografía inspiratoria habitual; TC/US en contextos específicos son más útiles. La afirmación «gran utilidad» está desactualizada.","o":{"A":"Derrame pleural loculado se define mejor con ecografía/TC.","C":"Neumotórax pequeño puede verse en radiografía, pero fase espiratoria forzada no aporta mayor sensibilidad demostrada.","D":"Hemotórax se estudia por imagen estándar y ecografía en trauma."},"src":"European Respiratory Society, Imaging of Pleural Disease","src_url":"https://publications.ersnet.org/highwire_display/entity_view/node/481635/full"});
Object.assign(KEY["pdf-novas-11"]["14"],{"a":"C","status":"validado","why":"Si FEV1/capacidad vital inspiratoria está al 104% del valor predicho, no evidencia reducción de la relación espirométrica que define obstrucción, aunque FEV1 aislado 76% esté reducido. Debe confirmar valores absolutos/Límite Inferior Normal para clasificar otros defectos.","o":{"A":"Obstrucción se define por relación FEV1/VC por debajo del límite inferior normal, no por FEV1 76% aislado.","B":"Obstrucción severa exige cociente obstructivo y FEV1 mucho más comprometido.","D":"Fibrosis pulmonar no se confirma por espirometría aislada; se requieren volúmenes pulmonares/TC según indicación."},"src":"ATS/ERS Standardization of Spirometry 2019","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6794117/"});
Object.assign(KEY["pdf-novas-11"]["15"],{"a":null,"status":"discutible","why":"Pregunta sin opción correcta: la evaluación de obstrucción de VÍA AÉREA SUPERIOR con espirometría se realiza principalmente mediante MORFOLOGÍA DE CURVA FLUJO-VOLUMEN (aplanamiento inspiratorio/espiratorio), no mediante CVF, FEV1, VRE ni VR aislados. Además el enunciado describe broncoespasmo de vía aérea inferior.","o":{"A":"CVF no identifica específicamente lesión extratorácica o intratorácica superior.","B":"FEV1 es indicador útil de obstrucción bronquial general, NO prueba específica de vía aérea superior.","C":"Volumen de reserva espiratorio no caracteriza curva de vías aéreas superiores.","D":"Volumen residual no se mide con espirometría simple y no es marcador específico de vía superior."},"src":"ATS/ERS Standardization of Spirometry 2019","src_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6794117/"});
Object.assign(KEY["pdf-novas-11"]["16"],{"a":"B","status":"validado","why":"Disnea súbita en paciente con insuficiencia cardiaca, crepitantes ascendentes y edema periférico sugiere edema agudo de pulmón cardiogénico; evaluar hipoxemia, PA, ECG, Rx o US y tratar insuficiencia cardiaca aguda.","o":{"A":"IAM puede precipitar edema, pero no es diagnóstico sindrómico principal de la presentación.","C":"Endocarditis precisa datos de infección, soplo nuevo o fenómenos embólicos, no descritos.","D":"NAC suele acompañarse de fiebre, foco respiratorio y condensación más localizada."},"src":"Australian Commission on Safety and Quality in Health Care, COPD Clinical Care Standard","src_url":"https://www.safetyandquality.gov.au/standards/clinical-care-standards/chronic-obstructive-pulmonary-disease-clinical-care-standard"});
Object.assign(KEY["pdf-novas-11"]["17"],{"a":"A","status":"discutible","why":"La penicilina V oral 500 mg dos veces/día por 10 días es opción de primera línea para faringitis confirmada por estreptococo A, PERO la penicilina benzatínica IM 1,2 millones U dosis única (C) también lo es, especialmente si adherencia oral incierta. Dos respuestas correctas: A y C. Mantener sin calificación hasta reformular.","o":{"B":"Penicilina V oral es válida si se puede asegurar 10 días de adherencia.","C":"Eritromicina se reserva como alternativa en alergia a penicilina y según resistencias.","D":"Penicilina benzatínica IM dosis única es opción equivalente aceptada."},"src":"CDC, Group A Strep Pharyngitis","src_url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/strep-throat.html"});
Object.assign(KEY["pdf-novas-11"]["18"],{"a":"A","status":"validado","why":"CRB-65: Confusión nueva, FR ≥30/min, presión sistólica <90 o diastólica ≤60 mmHg y edad ≥65 años. La opción A reproduce componentes aunque escribe >30 y >65, cuando el umbral exacto es ≥.","o":{"B":"La frecuencia cardíaca no sustituye frecuencia respiratoria.","C":"Crepitantes y SpO2 no son los cuatro criterios CRB-65.","D":"Creatinina corresponde a otros índices; no integra CRB-65."},"src":"NICE NG250, Pneumonia: diagnosis and management","src_url":"https://www.nice.org.uk/guidance/ng250/chapter/Recommendations"});
Object.assign(KEY["pdf-novas-12"]["1"],{"a":"A","status":"validado","why":"Metotrexato es un FAME convencional que modifica curso de artritis reumatoide y previene progresión estructural cuando se inicia precozmente y controla actividad.","o":{"B":"Glucocorticoides sistémicos pueden aliviar actividad a corto plazo pero no sustituyen FAME como control de fondo.","C":"AINE alivian síntomas, no detienen daño articular estructural.","D":"Infiltraciones corticoideas actúan localmente y no previenen progresión sistémica de AR."},"src":"EULAR recommendations for RA treatment with synthetic and biological DMARDs","src_url":"https://ard.bmj.com/content/83/1/3"});
Object.assign(KEY["pdf-novas-12"]["2"],{"a":null,"status":"discutible","why":"GABARITO ORIGINAL B NO DEMOSTRADO: la causa más frecuente de aplastamientos vertebrales atraumáticos en mujer de 55 años es OSTEOPOROSIS, que no aparece entre las opciones. Metástasis vertebrales son diagnóstico diferencial importante, pero no causa más frecuente global. Pregunta anulada.","o":{"A":"Tuberculosis vertebral es causa menos frecuente, con datos infecciosos variables.","B":"Metástasis es relevante y requiere descartarse según red flags, pero no supera osteoporosis como causa global.","C":"Paget puede debilitar hueso y deformar vértebras, pero es menos común.","D":"Osteoblastoma es tumor óseo benigno infrecuente, no explica la frecuencia general."},"src":"NOGG, UK Clinical Guideline for Osteoporosis and Fragility Fracture","src_url":"https://www.nogg.org.uk/full-guideline"});
Object.assign(KEY["pdf-novas-12"]["3"],{"a":"B","status":"validado","why":"La claudicación intermitente de pantorrilla suele relacionarse con enfermedad arterial femoropoplítea, típicamente estenosis de arteria FEMORAL SUPERFICIAL; claudicación glútea/muslo sugiere enfermedad aortoilíaca.","o":{"A":"Ilíaca externa suele producir síntomas más proximales, según circulación colateral.","C":"Femoral profunda es importante circulación colateral y menos habitual como lesión aislada causante de claudicación gemelar.","D":"Tibial posterior distal causa isquemia distal y no es sitio típico más frecuente de claudicación gemelar."},"src":"AHA/ACC 2024 PAD Guideline","src_url":"https://www.ahajournals.org/doi/10.1161/CIR.0000000000001251"});
Object.assign(KEY["pdf-novas-13"]["1"],{"a":"D","status":"validado","why":"Etanol desaparece de orina en menos tiempo que metabolitos de cannabis y muchos otros tóxicos incluidos en paneles de pesquisa habituales. La determinación específica de EtG/EtS tiene ventana mayor y NO forma parte de todos los paneles estándar.","o":{"A":"THC puede persistir días-semanas en consumidores frecuentes.","B":"Metabolitos de cocaína suelen detectarse durante días.","C":"Metabolitos de opioides como heroína suelen tener ventana de días según prueba."},"src":"SAMHSA, Clinical Drug Testing in Primary Care","src_url":"https://library.samhsa.gov/product/clinical-drug-testing-primary-care/sma12-4668"});
Object.assign(KEY["pdf-novas-13"]["2"],{"a":"B","status":"validado","why":"Ante mordedura de yarará, retirar anillos, pulseras, calzado y objetos constrictivos porque el edema progresivo puede comprometer perfusión. Inmovilizar miembro, traslado urgente y antiveneno sistémico según indicación; evitar torniquetes y técnicas locales.","o":{"A":"Lazo o torniquete puede empeorar lesión local/isquemia.","C":"Retirar objetos es intervención segura temprana por riesgo de edema.","D":"Inyecciones IM aumentan riesgo de sangrado con coagulopatía por veneno."},"src":"WHO, Snakebite Envenoming","src_url":"https://www.who.int/news-room/fact-sheets/detail/snakebite-envenoming"});
Object.assign(KEY["pdf-novas-13"]["3"],{"a":"A","status":"discutible","why":"Pregunta DESACTUALIZADA: ranitidina fue retirada en varios países a partir de 2020 por presencia/formación de NDMA; sin embargo FDA aprobó una formulación modificada el 24/11/2025. La situación de mercado varía por país, por lo que hoy la frase «salió del mercado» ya no tiene respuesta universal. El gabarito A histórico no debe puntuarse en 2026.","o":{"B":"Ranitidina fue retirada en 2020, pero existe formulación nuevamente aprobada en EE.UU. desde 2025.","C":"Omeprazol sigue disponible como inhibidor de bomba de protones.","D":"Pantoprazol sigue disponible como IBP."},"src":"FDA, Approved Reformulated Ranitidine 24 Nov 2025","src_url":"https://www.fda.gov/drugs/drug-safety-and-availability/fda-approves-reformulated-ranitidine-following-comprehensive-safety-review"});

Object.assign(KEY["pdf-novas-11"]["4"],{"o":{"A":"La resonancia y biopsia previas a toda estabilización pueden demorar tratamiento en un paciente comprometido.","B":"Radioterapia puede estar indicada según histología y urgencia, pero no sustituye evaluación de obstrucción y necesidad de stent.","D":"Completar imágenes sin valorar tratamiento urgente puede ser insuficiente ante compromiso respiratorio o circulatorio."}});
Object.assign(KEY["pdf-novas-11"]["7"],{"o":{"A":"El dímero D no confirma el TEP y no debe demorar tratamiento en choque.","B":"HBPM aislada sin valoración de reperfusión puede ser insuficiente en TEP de alto riesgo; considerar HNF si reperfusión es probable.","D":"Troponina y NT-proBNP ayudan a estratificar, pero no deben retrasar estabilización urgente."}});
Object.assign(KEY["pdf-novas-11"]["11"],{"o":{"A":"Tos es síntoma precoz pero no una alteración funcional respiratoria específica.","B":"Expectoración es manifestación clínica, no una primera prueba funcional objetiva.","D":"La disfunción del aclaramiento mucociliar puede aparecer tempranamente y revertir parcialmente al dejar de fumar; por ello C no es única."}});
Object.assign(KEY["pdf-novas-11"]["13"],{"o":{"A":"Los derrames pleurales loculados se valoran mejor con ecografía o TC.","C":"El hemotórax se diagnostica por imágenes torácicas estándar y ecografía traumática, no por espiración forzada.","D":"La atelectasia se evalúa por signos radiográficos de pérdida de volumen, no preferentemente por espiración forzada."}});
Object.assign(KEY["pdf-novas-11"]["17"],{"o":{"B":"Eritromicina puede utilizarse como alternativa en alergia a betalactámicos según susceptibilidad; no es la primera opción en no alérgico.","C":"La penicilina benzatínica 1.200.000 UI IM única también es tratamiento de primera línea adecuado; hace la pregunta ambigua.","D":"Amoxicilina durante solo 5 días no corresponde al régimen oral convencional de diez días."}});
Object.assign(KEY["pdf-novas-13"]["2"],{"o":{"A":"Aplicar torniquete o lazo puede empeorar isquemia y necrosis.","C":"Evitar inyecciones intramusculares por riesgo de sangrado en coagulopatía.","D":"El antiveneno no se infiltra localmente; requiere administración sistémica supervisada."}});
Object.assign(KEY["pdf-novas-13"]["3"],{"o":{"B":"Omeprazol sigue disponible como inhibidor de la bomba de protones.","C":"Pantoprazol sigue disponible como inhibidor de la bomba de protones.","D":"Esomeprazol sigue disponible como inhibidor de la bomba de protones."}});

